(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c48"]=[{"id":"00012512","register_sub_id":"101","register_pk":"367807","name":"旧今福家住宅裏門","kana":"きゅういまふくけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県海老名市中新田一丁目1495-5","lat":35.439892,"lng":139.386185,"geo_status":"geocoded","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造、間口1.6m","structure_material":"石造","registered":"2018.11.02(平成30.11.02)","register_no":"14 － 0261","desc":"もと名主宅の通用門で、敷地東面を流れる水路に面して建つ。18センチ角の石柱を間口1･6メートルで立て、柱頂に石製の冠木を渡す。冠木上には「今」をアールヌーヴォー風に図案化した鉄製飾を載せる。旧家の近代の暮らしの一端を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012512"},{"id":"00012511","register_sub_id":"101","register_pk":"367806","name":"旧今福家住宅表門及び塀","kana":"きゅういまふくけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県海老名市中新田一丁目1495-5","lat":35.439892,"lng":139.386185,"geo_status":"geocoded","era":"嘉永6年（1853）／明治27年・大正期改修","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"表門 木造、瓦葺、間口2.7m、左右袖塀及び北方潜戸付 塀 木造、金属板葺、総延長26m","structure_material":"表門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"14 － 0260","desc":"もと名主宅の正門で、敷地西面南寄りに通りから後退して開く。桟瓦葺の一間薬医門で、両脇に縦板張目板打の袖塀を延ばし、北側に潜戸を付す。柱、冠木とも見付が大きく、妻壁を笈形風の透彫、塀の欄間を襷格子で飾るなど、旧家の表構えの格式を備える門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012511"},{"id":"00012510","register_sub_id":"101","register_pk":"367805","name":"旧今福家住宅文庫蔵","kana":"きゅういまふくけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県海老名市中新田一丁目1495-5","lat":35.439892,"lng":139.386185,"geo_status":"geocoded","era":"弘化4年（1847）／明治22年・昭和前期・平成19年改修","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積37㎡","structure_material":"土蔵造3階建","registered":"2018.11.02(平成30.11.02)","register_no":"14 － 0259","desc":"もと名主宅の土蔵で、敷地西側の北寄りに建つ。南北棟の切妻造桟瓦葺で、鉢巻を二段に廻し、東面北寄りの戸口を設けて下屋を付す。外観は二階建にみせるが内部は三層で、妻側の窓の内戸を斜めに取付ける特異な形式をもつ。上層農家の屋敷構えの構成を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012510"},{"id":"00011898","register_sub_id":"101","register_pk":"211063","name":"旧内野醤油店新座敷","kana":"きゅううちのしょうゆてんしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪598他","lat":35.247641,"lng":139.14224,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0237","desc":"店舗兼主屋の西に張出す角屋で、通りから前庭を介して建つ。木造平屋建、入母屋造桟瓦葺で、正背面に下屋を設ける。内部は八畳一室で丸太柱を使い、西面に甕形の墨跡窓を開けた床を設け、東面に茶道具を納める洞庫を造り付ける。瀟洒な意匠の隠居部屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011898"},{"id":"00013370","register_sub_id":"101","register_pk":"368457","name":"旧太田家住宅主屋（宝善院三摩耶庵）","kana":"きゅうおおたけじゅうたくおもや（ほうぜんいんさんまやあん）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市腰越五丁目306-1他","lat":35.31249722,"lng":139.49595,"geo_status":"db","era":"昭和11年／昭和16年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積307㎡","structure_material":"木造平屋一部2階建","registered":"2020.08.17(令和2.08.17)","register_no":"14 － 0283","desc":"鎌倉市南西部の宝善院境内地にある木造の和洋折衷住宅。葛西萬司の設計による。木造平屋建一部二階建、寄棟造瓦葺で、中廊下の南を和室とし、南側の庭園に面して広縁を設ける。南西隅に洋風の外観で玄関ポーチや洋室を配し、和洋の意匠を巧みに融合する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013370"},{"id":"00011914","register_sub_id":"101","register_pk":"354918","name":"旧加地邸","kana":"きゅうかちてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県三浦郡葉山町一色字菖蒲沢1706","lat":35.265793,"lng":139.581708,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造一部鉄筋コンクリート造2階一部地下1階建、銅板葺、建築面積297㎡","structure_material":"木造一部鉄筋コンクリート造2階一部地下1階建","registered":"2017.10.27(平成29.10.27)","register_no":"14-253","desc":"遠藤新の設計の住宅。大谷石敷のアプローチから玄関を入り、南にテラス、サンルームを有する居間を中心として東に寝室、西に食堂等、暖炉の背面側に撞球室を配する。大谷石の多用、水平に大きく伸びる軒などプレーリースタイルでまとめるライト風住宅の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011914"},{"id":"00005735","register_sub_id":"101","register_pk":"106723","name":"旧華頂家住宅主屋","kana":"きゅうかちょうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市浄明寺2-486-1他","lat":35.318199,"lng":139.569839,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造地上3階地下1階建、銅板葺、建築面積315㎡","structure_material":"木造地上3階地下1階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0124","desc":"敷地北寄りに建ち，南にフランス式庭園を配す。木造２階建，地階及び屋階を設け，切妻造，銅板葺。外観はハーフティンバー形式で一部タイル貼とする。内部は前後２列に室を配し，背面に平屋のサービス棟を附属する。幾何学的な庭園と共に端正な趣の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005735"},{"id":"00013516","register_sub_id":"101","register_pk":"504880","name":"旧金子堅太郎葉山別邸恩賜松荘","kana":"きゅうかねこけんたろうはやまべっていおんしまつそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県三浦郡葉山町一色字三ケ岡2311-1","lat":35.2662,"lng":139.57536389,"geo_status":"db","era":"大正11年頃／昭和30年増改築、平成19年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平家建、瓦葺、建築面積199㎡","structure_material":"木造平家建","registered":"2021.02.04(令和3.02.04)","register_no":"14 － 0289","desc":"葉山御用邸に近く、海に面した景勝地に位置する。南北棟にわかれ、南棟は平屋建切妻造桟瓦葺で玄関から居間、食堂を配する。北棟は平屋建寄棟造桟瓦葺で表に座敷、食堂、背面に洋室等をおく。銘木を用い欄間など細部まで意匠を凝らした上質な別邸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013516"},{"id":"00013517","register_sub_id":"101","register_pk":"504881","name":"旧金子堅太郎葉山別邸米寿荘","kana":"きゅうかねこけんたろうはやまべっていべいじゅそう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県三浦郡葉山町一色字三ケ岡2311-6","lat":35.266525,"lng":139.57533333,"geo_status":"db","era":"昭和15年頃／昭和25年頃増築、平成18年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、瓦葺、建築面積169㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"14 － 0290","desc":"恩賜松荘の東に建つ。二階建入母屋造桟瓦葺。玄関から入って田の字形の四間取とし、奥に食堂を別棟で接続する。二階にも四室配する。一階は民家を移築したと伝え農家風意匠とし、二階は銘木を用いた数寄屋風意匠とする。葉山の別荘の歴史を物語る上で重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013517"},{"id":"00013512","register_sub_id":"101","register_pk":"504876","name":"旧川喜多家別邸（石島家住宅）主屋","kana":"きゅうかわきたけべってい（いしじまけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市雪ノ下一丁目155","lat":35.32396944,"lng":139.55291667,"geo_status":"db","era":"昭和17年頃／平成6年改修","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階一部平屋建、石綿セメント板葺一部鉄板葺、建築面積133㎡","structure_material":"木造2階一部平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"14 － 0285","desc":"実業家川喜多長政の別邸。木造二階建の洋館で、玄関は北東隅に半円アーチの開口をつくりポーチとする。内部は南側を主要居室にあてる。モルタル仕上の壁面と白の窓枠に特徴付けられた瀟洒な外観は、戦前の鎌倉の住宅のたたずまいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013512"},{"id":"00015004","register_sub_id":"101","register_pk":"529282","name":"旧川本家住宅内蔵","kana":"きゅうかわもとけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県横浜市西区西戸部町一丁目13","lat":35.449725,"lng":139.62271111,"geo_status":"db","era":"明治32年／昭和8年移築","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"14 - 0349","desc":"主屋北西に接続する家財蔵。二階建切妻造妻入桟瓦葺で南北棟の小規模な土蔵で、外壁は漆喰塗仕上とし、軒に鉢巻を廻す。北面に２箇所の窓を開け、庇持送には繰形を付す。各階一室の板敷。隧道開削以前から存在しつつ、外観重厚ながら主屋と良く調和した土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015004"},{"id":"00015005","register_sub_id":"101","register_pk":"529283","name":"旧川本家住宅表門及び石垣","kana":"きゅうかわもとけじゅうたくおもてもんおよびいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市西区西戸部町一丁目14-2他","lat":35.44959167,"lng":139.62286667,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"表門 木造、瓦葺、間口1.8m、左右袖塀及び石段付 石垣 石造、総延長70m","structure_material":"表門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"14 - 0350","desc":"主屋玄関東側に配した表門と、敷地東面及び北面を矩折れに区画する石垣。緩やかな石段上に建つ表門は、間口一間切妻造平入桟瓦葺袖塀付きで屋根に起りを付す。石垣は凝灰岩のブラフ積で上部に低い石塀を載せる。いずれも丁寧なつくりで屋敷の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015005"},{"id":"00015003","register_sub_id":"101","register_pk":"529281","name":"旧川本家住宅主屋","kana":"きゅうかわもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市西区西戸部町一丁目13","lat":35.44970556,"lng":139.62279722,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺一部鉄板葺、建築面積231㎡","structure_material":"木造平屋一部2階建","registered":"2024.08.15(令和6.08.15)","register_no":"14 - 0348","desc":"横浜港北西の丘陵に位置し、京浜電気鉄道の隧道開削に伴い新築した平屋建の主屋。内部は廊下や部屋境の棚の配置などで各室の独立性を高めた近代的な平面。寄木張床の応接室を含め外観和風で統一し、繊細な意匠の建具や随所に銘木を用いた良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015003"},{"id":"00009131","register_sub_id":"101","register_pk":"164684","name":"旧木下家別邸","kana":"きゅうきのしたけべってい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県中郡大磯町大磯字北本町1007イ号2","lat":35.31104431,"lng":139.31450665,"geo_status":"db","era":"大正元年／平成元年・平成18年改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造地上2階一部地下1階建、スレート葺、建築面積94㎡","structure_material":"木造地上2階一部地下1階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"木造2階1部地下1階建で屋根裏部屋を備える。建築面積94平方メートル、切妻造スレート葺で、左右の屋根上にドーマー窓を開く。正面中央に玄関ポーチを構え、外壁は下見板張とし、各室にベイウィンドウを設ける。別荘地大磯に残る数少ない洋風の別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009131"},{"id":"00002894","register_sub_id":"101","register_pk":"103884","name":"旧近藤邸","kana":"きゅうこんどうてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市鵠沼東8-1","lat":35.332912,"lng":139.48909,"geo_status":"db","era":"大正14／昭和56移築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、スレート葺、建築面積173㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"14 － 0068","desc":"市内辻堂東海岸から移築保存した実業家の別荘で，設計は遠藤新。木造で平面はＴ字形になり，交差部を一部２階建とし，屋上露台と連続する。外観は下見板張や軒板などで水平線を強調した造形や，庭側のテラス，建具などに，ライト風の意匠が顕著にみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002894"},{"id":"00010751","register_sub_id":"101","register_pk":"201586","name":"旧笹野家住宅主屋","kana":"きゅうささのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県相模原市緑区上九沢字寺上76","lat":35.582522,"lng":139.326286,"geo_status":"db","era":"江戸末期／明治2移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積211㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"14 ‐ 0196","desc":"敷地中央に西面して建つ寄棟造で、せがい造の軒と縁を廻らせる。床上部は六間取系で表列上手の室に座敷飾を備え、中央のナカノマ前面はもと式台を構えた。奥列は土間に居室を広く張出し、小屋には簀子張の養蚕の設えを残す。規模形式とも充実した近世民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010751"},{"id":"00010752","register_sub_id":"101","register_pk":"201587","name":"旧笹野家住宅長屋門","kana":"きゅうささのけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県相模原市緑区上九沢字寺上76","lat":35.582249,"lng":139.326115,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"14 ‐ 0197","desc":"敷地西辺、主屋のやや斜め前方に構える。間口六間半の長屋門で、軒をせがいに造り、入母屋造鉄板葺である。中央間を門口としてケヤキの板戸を吊り、南側に潜戸を開く。左右の室は正面を簓子下見板張とし、内部は土間床である。旧家の屋敷景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010752"},{"id":"00014147","register_sub_id":"101","register_pk":"508777","name":"旧正力家別邸主屋","kana":"きゅうしょうりきけじゅうたくべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県逗子市新宿三丁目1953他","lat":35.29708889,"lng":139.56916111,"geo_status":"db","era":"昭和前期／同14年改修・同36年増築・平成28年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積200㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"14-0305","desc":"逗子海岸の北に位置する別邸。東の玄関から南庭に面して、部屋を雁行して並べ、南東に書院造の座敷を配す。座敷上部に設けた洋室は、庭を臨む三面にガラス窓を入れ、開放的な造りとする。洋室の外部には欄干付の縁を巡らし、外観を和風にまとめた良質な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014147"},{"id":"00014149","register_sub_id":"101","register_pk":"508779","name":"旧正力家別邸表門","kana":"きゅうしょうりきけべっていおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県逗子市新宿三丁目1953","lat":35.2971,"lng":139.56933056,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造、銅板葺、間口1.8m、左右袖塀付","structure_material":"木造","registered":"2022.02.17(令和4.02.17)","register_no":"14-0307","desc":"主屋の東に位置し、通りに東面する腕木門。主柱と冠木は皮付丸太で、主柱は角柱の控柱と貫で固める。主柱で棟木を直接受け、軒桁を腕木で支持する。門口に板戸を吊り、屋根は銅板葺で棟は熨斗積とする。両脇に袖塀を付して屋敷表構えを整える数寄屋風の表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014149"},{"id":"00014148","register_sub_id":"101","register_pk":"508778","name":"旧正力家別邸蔵","kana":"きゅうしょうりきけべっていくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県逗子市新宿三丁目1953他","lat":35.29705,"lng":139.56903333,"geo_status":"db","era":"昭和34年／平成28年改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積24㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"14-0306","desc":"主屋西側に位置する蔵。鉄筋コンクリート造二階建、切妻造妻入の東西棟で、東面に戸口を設け、各階南北面中央に窓を開けて鉄扉を備える。外壁はリシン吹付仕上で、腰は刷毛引仕上。内部は各階とも一室で南東隅に階段を設ける。主屋西側の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014148"},{"id":"00013514","register_sub_id":"101","register_pk":"504878","name":"旧豊島家住宅主屋","kana":"きゅうとしまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市栄町四丁目700-1","lat":35.25641389,"lng":139.16285278,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平家建、瓦葺、建築面積119㎡","structure_material":"木造平家建","registered":"2021.02.04(令和3.02.04)","register_no":"14 － 0287","desc":"小田原中心部の旧武家地に位置。通りから広い前庭を介して建ち、平屋建入母屋造桟瓦葺で、庭に面して入母屋の妻を両端に掲げ格式を高める。玄関両脇に二室、奥に庭に面した縁側を通して八畳、六畳、四畳半を並べる。端正な座敷を有する上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013514"},{"id":"00013515","register_sub_id":"101","register_pk":"504879","name":"旧豊島家住宅門及び塀","kana":"きゅうとしまけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市栄町四丁目700-1","lat":35.256275,"lng":139.16292778,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"門 木造、瓦葺、間口2.1m 塀 木造、瓦葺、延長28m","structure_material":"門 木造","registered":"2021.02.04(令和3.02.04)","register_no":"14 － 0288","desc":"通りに面して塀を巡らし表門を開ける。門は腕木門形式で切妻造桟瓦葺とし、冠木等に丸太を使う数寄屋風意匠をとる。左右塀は基礎を大谷石、腰を板張、上部を漆喰塗として桟瓦を葺く。総延長二八メートル。主屋とともに城下町の旧武家地の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013515"},{"id":"00013061","register_sub_id":"101","register_pk":"368244","name":"旧長谷川家住宅石蔵","kana":"きゅうはせがわけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県三浦市初声町三戸字上ノ原2593-1他","lat":35.17225,"lng":139.62188333,"geo_status":"db","era":"明治中期／昭和前期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木骨石造2階建、瓦葺、建築面積37㎡","structure_material":"木骨石造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0277","desc":"主屋南東に南北棟で建つ。二階建、切妻造、置屋根形式の桟瓦葺で、西面中央に戸口を開き、吹放しの下屋を付す。当初は土蔵造だが、後の改修で柱の外側に切石を積み、折釘等で軸部と緊結する。戸口廻りの持送も技巧的で、地域の技術的な特徴を備える旧家の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013061"},{"id":"00013060","register_sub_id":"101","register_pk":"368243","name":"旧長谷川家住宅主屋","kana":"きゅうはせがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県三浦市初声町三戸字上ノ原2593-1他","lat":35.17238889,"lng":139.62182778,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0276","desc":"敷地北寄りに南面して建ち、周囲に下屋を廻らし正面中央に入母屋造の玄関を張出す。玄関奥に神棚付和室と仏間を前後に並べ、東側に接客用の端正な主座敷を配する。さらに東に連なる離れは瀟洒な数寄屋として趣を変える。三浦半島沿岸部の良質な昭和初期住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013060"},{"id":"00013062","register_sub_id":"101","register_pk":"368245","name":"旧長谷川家住宅庭門及び内塀","kana":"きゅうはせがわけじゅうたくにわもんおよびうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県三浦市初声町三戸字上ノ原2593-1他","lat":35.17228333,"lng":139.62183611,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"門 木造、銅板葺、間口1.2m 塀 木造、銅板葺、総延長4.1m","structure_material":"門 木造","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0278","desc":"主屋玄関の南東隅柱と石蔵の下屋柱の間に建つ庭門と左右の内塀。庭門は腕木門で親柱を出節の磨き丸太とし、軒廻りに丸太を使うなど数寄屋風のつくりとする。内塀は腰高に竪板張を細竹の押縁で押さえ、軒を薄くつくり、庭門と調和した繊細な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013062"},{"id":"00013055","register_sub_id":"101","register_pk":"368238","name":"旧原家住宅稲荷社","kana":"きゅうはらけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県川崎市中原区小杉陣屋町一丁目561-11他","lat":35.583375,"lng":139.65875556,"geo_status":"db","era":"明治後期／平成27年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0271","desc":"中原街道に面する旧家の屋敷地の南寄りで、覆屋内に北面して建つ。一間社流造銅板葺で正面に軒唐破風を付し、四周廻らす縁を腰組で支える。組物は出組の詰組で、各間に蟇股を置き、向拝海老虹梁には角状の飾りを付ける。小規模ながら上質なつくりの社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013055"},{"id":"00013056","register_sub_id":"101","register_pk":"368239","name":"旧原家住宅表門","kana":"きゅうはらけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県川崎市中原区小杉陣屋町一丁目561-7","lat":35.58333056,"lng":139.65868056,"geo_status":"db","era":"明治後期／平成4年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0272","desc":"敷地南面中央に建つ一間薬医門。切妻造桟瓦葺で、2・7メートルの間口に門扉を開く。五平の本柱に縦長の冠木を渡し、軒は一軒疎垂木とし、破風の拝みに大振の雲紋彫刻の懸魚を飾る。簡素ながら良質なケヤキ材を用いており、旧家の屋敷構の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013056"},{"id":"00012509","register_sub_id":"101","register_pk":"367804","name":"旧氷室家住宅主屋","kana":"きゅうひむろけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県茅ヶ崎市東海岸南三丁目11335-1","lat":35.319965,"lng":139.4095,"geo_status":"geocoded","era":"昭和10年／昭和35年・平成12年増築","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積152㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"14 － 0258","desc":"実業家のもと別荘で、前庭を控え敷地北西に建つ。西半は板敷の居間中心に開放的につくり、床下換気装置等に住宅改良の一端が窺える。東半は緩勾配の深い軒や直線的構成などモダンな和風意匠とする。昭和期の住宅思潮と茅ヶ崎の別荘地開発の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012509"},{"id":"00014774","register_sub_id":"101","register_pk":"519032","name":"旧平野家住宅主屋","kana":"きゅうひらのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県三浦郡葉山町堀内字牛ヶ谷1834","lat":35.27253056,"lng":139.57988889,"geo_status":"db","era":"昭和11年／昭和13年頃増築、令和2年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0342","desc":"ＪＲ逗子駅と葉山御用邸を結ぶ国道の近傍に建つ。木造平屋建、桟瓦葺で、庭に面して濡縁・榑縁付の座敷を雁行状に配し、背面には随所に銘木を用いた中二階の座敷を接続する。材木商による上質な近代和風住宅で、昭和前期に葉山に築かれた郊外住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014774"},{"id":"00014341","register_sub_id":"101","register_pk":"511330","name":"旧本多家住宅主屋","kana":"きゅうほんだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県逗子市山の根二丁目297","lat":35.29910556,"lng":139.58055556,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、スレート葺、建築面積216㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0319","desc":"逗子駅近くの山裾に建つ洋風住宅。外観はモルタル仕上大壁で、開口部廻りに擬石をあしらい、バルコニー腰壁にメダリオンを飾る。正面西にポーチと玄関、東に吹抜の居間を配す。久米権九郎の設計で、束ね式の小柱と横架材を用いた独自の耐震木構造による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014341"},{"id":"00015420","register_sub_id":"101","register_pk":"533435","name":"旧松野家住宅表門及び塀","kana":"きゅうまつのけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市磯子区滝頭三丁目180-1","lat":35.41893889,"lng":139.62411944,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"表門 木造、瓦葺、間口2.0m 塀 木造、瓦葺、総延長23m","structure_material":"表門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"14 - 0361","desc":"主屋玄関の南、引込み路に南面して開く腕木門と塀。表門は切妻造桟瓦葺で二段に腕木を重ねる。両脇に延びる塀は桟瓦葺で、表門と揃えて二段に腕木を重ね、門両脇の腰を竪板張に竹目板打とする以外は下見板張とする。敷地南面の歴史的な景観を整える表門と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015420"},{"id":"00015419","register_sub_id":"101","register_pk":"533434","name":"旧松野家住宅主屋","kana":"きゅうまつのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市磯子区滝頭三丁目180","lat":35.41912778,"lng":139.62408611,"geo_status":"db","era":"昭和5年／昭和47年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"14 - 0360","desc":"堀割川の西に位置する地主の本宅。敷地中央に南面して建つ寄棟造桟瓦葺の平屋建で正面東寄りに入母屋造の玄関を付す。内部は南西のオクノマ八畳に床構えを備え、玄関の東にチャノマ、北にダイドコロを配す。床框に紫檀など吟味し、良材を用いた近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015419"},{"id":"00009742","register_sub_id":"101","register_pk":"195571","name":"旧三觜八郎右衛門家住宅主屋","kana":"きゅうみつはしはちろうえもんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市羽鳥3-1039-1他","lat":35.34516414,"lng":139.45770521,"geo_status":"db","era":"明治11／昭和前期改修","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0182","desc":"東海道の南方の敷地に西面し、二階建、切妻造桟瓦葺である。南寄りの土間や板の間では、ケヤキなどの良質な柱や差物を堅牢に組む。また床上部は六間取で、座敷廻りでは襖に山水画を描くほか、透彫欄間や釘隠金具等の造作も入念で、格調高い室内意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009742"},{"id":"00009743","register_sub_id":"101","register_pk":"195572","name":"旧三觜八郎右衛門家住宅門","kana":"きゅうみつはしはちろうえもんけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市羽鳥3-1039-1他","lat":35.34520697,"lng":139.45743395,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.7m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0183","desc":"主屋の前方に西面して建つ。薬医門、切妻造桟瓦葺である。両脇に潜戸付きの袖塀を設け、取付部に絵様付きの柄振板を入れる。部材木口を白塗とし、扉の金具類も古式である。冠木や男梁等の材も太く、風格ある外観を持つ。屋敷の正門に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009743"},{"id":"00015423","register_sub_id":"101","register_pk":"533438","name":"旧山川家住宅主屋","kana":"きゅうやまかわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県中郡二宮町二宮字西向浜97-67","lat":35.29644167,"lng":139.2587,"geo_status":"db","era":"昭和18年／昭和45年頃・平成10年頃改修","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積109㎡","structure_material":"木造2階一部平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"14 - 0364","desc":"二宮駅から海岸に通じる緩やかな坂道に東面する日本画家山川秀峰の住宅。木造二階建、切妻造のシンプルな外観で、かつて海を望んだ南側に画室や居室を並べる。画室は和小屋を現し、一部丸竹詰張の天井を張るなど民家風の趣味を取入れた貴重な吉田五十八作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015423"},{"id":"00012725","register_sub_id":"101","register_pk":"367628","name":"旧吉田茂邸兜門","kana":"きゅうよしだしげるていかぶともん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県中郡大磯町国府本郷字切通551-1","lat":35.30571583,"lng":139.28232583,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造、檜皮葺、間口3.3m","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 270","desc":"前庭と内庭を画し、北面して建つ寄棟造檜皮葺の門。間口三・三メートルで本柱を立て、背後に控柱、左右に袖塀を付す。本柱や棟木、垂木等に丸太材を用い、背面の屋根を葺下ろして軒先中央を半円形に切欠く。裏千家今日庵の兜門に倣った上質な数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012725"},{"id":"00012723","register_sub_id":"101","register_pk":"367626","name":"旧吉田茂邸サンルーム","kana":"きゅうよしだしげるていさんるーむ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県中郡大磯町国府本郷字切通504-3","lat":35.30571583,"lng":139.28232583,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨造、面積55㎡","structure_material":"鉄骨造","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 268","desc":"大磯海岸沿いにある政治家・吉田茂の旧邸。サンルームは主屋西北隅の人工地盤上に建ち、内庭側の南面にテラスを設ける。吉田五十八の設計で、細身の鉄骨材による骨組や軒を曲面としたポリカーボネート屋根など、現代的な材料を繊細かつ優美な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012723"},{"id":"00012724","register_sub_id":"101","register_pk":"367627","name":"旧吉田茂邸七賢堂","kana":"きゅうよしだしげるていしちけんどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県中郡大磯町国府本郷字小磯境503-2","lat":35.30571583,"lng":139.28232583,"geo_status":"db","era":"明治36年頃／昭和35年移築","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積8.3㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 269","desc":"伊藤博文旧邸から移築した近代の元勲を祀った祠堂。内庭の一角に西面して建つ二間四方の入母屋造銅板葺で、正面は虹梁を通して桟唐戸風の引戸を入れる。組物は平三斗、軒は二軒で、正面を平行垂木、側背面を扇垂木とする。良材を用いた丁寧なつくりの小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012724"},{"id":"00013057","register_sub_id":"101","register_pk":"368240","name":"旧吉原家別邸主屋","kana":"きゅうよしわらけべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市佐助一丁目554-1","lat":35.32156667,"lng":139.54322778,"geo_status":"db","era":"昭和8年頃／平成5年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造及び木造地上2階地下1階建、スレート葺、建築面積116㎡","structure_material":"鉄筋コンクリート造及び木造地上2階地下1階建","registered":"2019.12.05(令和1.12.05)","register_no":"14 － 0273","desc":"鎌倉駅西方の住宅地に北面して建つ。木造二階建、寄棟造スレート葺で、庭側に半円平面のサンルームを張出し、外壁はプラスター塗とスクラッチタイルで仕上げる。昭和初期に東京の実業家が郊外住宅地に建て、和洋折衷の形式をもつ別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013057"},{"id":"00008100","register_sub_id":"101","register_pk":"132498","name":"旧脇村家住宅主屋","kana":"きゅうわきむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県逗子市桜山8-2241","lat":35.28900039,"lng":139.57683165,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積247㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"14 － 0164","desc":"南・西面を望見するように１階に居間、２階に客間を配する木造２階建、寄棟造桟瓦葺、その東南に茶室棟、北東に台所等を配する。建築面積２４７㎡。銘木を使い、数寄屋風意匠を有する一方、陽光を意識した棟配置と広い開放感が海浜別荘らしさを醸出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008100"},{"id":"00004728","register_sub_id":"101","register_pk":"105718","name":"光明寺書院","kana":"こうみょうじしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県横浜市南区庚台66","lat":35.44275059,"lng":139.60982579,"geo_status":"db","era":"明治33／大正13移築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0109","desc":"小田原御用邸の常宮御座所を移築。入母屋造，桟瓦葺で，１２畳２室，１０畳２室を田の字に配し，南側の１間幅の畳廊下は居室に取り込まれている。南北に板縁，東西に１間幅の畳廊下がつく。近代和風の宮廷建築として貴重。設計は宮内省内匠寮の鵜飼源三郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004728"},{"id":"00010754","register_sub_id":"101","register_pk":"201589","name":"小島家住宅蔵","kana":"こじまけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県厚木市飯山字栗原4496-1","lat":35.471112,"lng":139.317117,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造平屋一部2階建、銅板葺、建築面積50㎡","structure_material":"土蔵造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"14 ‐ 0199","desc":"主屋北西側に東西棟で建つ。桁行一〇メートル梁間三・六メートル、土蔵造、置屋根式の桟瓦葺である。外壁漆喰塗で鉢巻を廻らし、腰を黒漆喰で引締める。内部は東の文庫蔵、西の穀蔵に二分され、各々南面に戸口を設けて土塗の引戸を吊り、両妻に窓を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010754"},{"id":"00010753","register_sub_id":"101","register_pk":"201588","name":"小島家住宅主屋","kana":"こじまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県厚木市飯山字栗原4496-1","lat":35.471033,"lng":139.317257,"geo_status":"db","era":"明治18頃／昭和48頃・平成5頃改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、茅葺（銅板仮葺）、建築面積168㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"14 ‐ 0198","desc":"厚木市北郊の段丘上の敷地に南面し、屋根は正側面とも切上げて兜造とする。東寄りを土間とし、居室は食違い四間取で土間寄付のザシキは広い一五畳である。成の高い差物で軸部を堅牢に固め、西側の二室は造作にクロガキを多用するなど上質な普請の養蚕民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010753"},{"id":"00010755","register_sub_id":"101","register_pk":"201590","name":"小島家住宅門","kana":"こじまけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県厚木市飯山字栗原4496-1","lat":35.470826,"lng":139.317269,"geo_status":"db","era":"明治20頃／昭和44移築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"14 ‐ 0200","desc":"敷地南面中央から奥寄りの斜路上に構える表門。一間薬医門、切妻造桟瓦葺で、東西に袖塀を設け、東袖塀に潜戸を開く。本柱と控柱の桁に三筋の梁を架けて桁を受け、一軒疎垂木とする。いずれもケヤキの良材を用いており、立地とともに屋敷構えを引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010755"},{"id":"00007465","register_sub_id":"101","register_pk":"108447","name":"古民家山十邸主屋","kana":"こみんかやまじゅうていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県愛甲郡愛川町中津字松台485-5他","lat":35.51576133,"lng":139.33077589,"geo_status":"db","era":"明治16／平成元改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積305㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"14 － 0152","desc":"中津川沿いの通りに西面する敷地の中央に建つ。桁行２３ｍ梁間１３ｍの大規模な農家で、入母屋造桟瓦葺とし、西正面中央北寄りに式台を設ける。南側に土間、北側に２列各３室の六間取。北端には座敷飾りを備える１５畳の主座敷を設けるなど、豪壮な農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007465"},{"id":"00007466","register_sub_id":"101","register_pk":"108448","name":"古民家山十邸門","kana":"こみんかやまじゅうていもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県愛甲郡愛川町中津字松台485-5","lat":35.51565308,"lng":139.33055269,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"14 － 0153","desc":"通りから石段を上がったところに西面して建つ。間口２．８ｍと大型の一間薬医門で、両脇に袖塀を付ける。切妻造桟瓦葺。本柱上に冠木、男梁を架け、一軒疎垂木。両開戸を構え、南袖塀に潜りを穿つ。簡明な構造で、部材が太く、力感にあふれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007466"},{"id":"00013780","register_sub_id":"101","register_pk":"507695","name":"齋藤家住宅石蔵","kana":"さいとうけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市本鵠沼五丁目3284-1","lat":35.336325,"lng":139.47254167,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積43㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"14 － 0300","desc":"主屋の背面に南面して建つ二階建の石蔵。桁行三間半、梁間二間半の規模で、木造軸組の外面に大谷石を積み、要所を柱から鎹で引付ける。屋根は切妻造波形鉄板葺とし、二階の東妻壁に窓を設ける。当地において大谷石積を化粧で現した石蔵の遺例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013780"},{"id":"00013779","register_sub_id":"101","register_pk":"507694","name":"齋藤家住宅主屋","kana":"さいとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市本鵠沼五丁目3284-1","lat":35.33638889,"lng":139.472375,"geo_status":"db","era":"明治20年／大正3年増築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、茅葺(鉄板仮葺)、建築面積227㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"14 － 0299","desc":"代々鵠沼の名主を務めた旧家の主屋。敷地中央に西面して建つ。桁行九間梁間四間半、整形六間取の大型民家で一部に中二階を設ける。入母屋造茅葺（鉄板仮葺）で軒は出桁造。二重梁の上に扠首組を架ける小屋組は、県下幕末期の大型上層民家の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013779"},{"id":"00013781","register_sub_id":"101","register_pk":"507696","name":"齋藤家住宅長屋門","kana":"さいとうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市本鵠沼五丁目3284-1","lat":35.33648611,"lng":139.472175,"geo_status":"db","era":"明治23年／昭和前期増築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積75㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"14 － 0301","desc":"街路に面して建つ。桁行七間半梁間二間、中央二間に門口、両脇に部屋を配し、部屋前方に下屋を付す。屋根は寄棟造茅葺（鉄板仮葺）で軒を出桁造とし疎垂木を配る。門口回りは欅材を用い、本柱を立て冠木で繋ぎ、板戸両開きを吊る。屋敷の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013781"},{"id":"00010128","register_sub_id":"101","register_pk":"197961","name":"坂井家住宅洋館","kana":"さかいけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市扇ガ谷4-506-3他","lat":35.328696,"lng":139.548118,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、スレート葺、建築面積49㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"14 － 0189","desc":"和館の南東隅に接続して建つ木造二階建の建物。敷地の高低差を利用し、洋館の二階に和館の一階を接続する。外壁はモルタル塗リシン吹付とし、二階出窓の上下に見切を入れるなど、和館と対照的に見せる。二階を洋風の応接室として、洋館併設住宅の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010128"},{"id":"00010127","register_sub_id":"101","register_pk":"197960","name":"坂井家住宅和館","kana":"さかいけじゅうたくわかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市扇ガ谷4-505他","lat":35.328737,"lng":139.547975,"geo_status":"db","era":"昭和2／昭和16頃改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"14 － 0188","desc":"扇ガ谷の奥寄りに坂井英太郎の鎌倉別邸として建築された。木造二階建で、南面して建ち、正面東寄りに玄関を構え、背面東寄りに家政部を張出す。南面の開口を広めて採光するほか、玄関や取次の間、背面廊下を広めに作り、家政部分にも配慮がみられる別邸建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010127"},{"id":"00002897","register_sub_id":"101","register_pk":"103887","name":"山月（旧共寿亭）","kana":"さんげつ（きゅうきょうじゅてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字香林寺山870-1","lat":35.250046,"lng":139.143402,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、銅板葺、建築面積200㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"14 － 0071","desc":"木造・一部２階建の別荘で，相模湾を見下ろす景勝の地に建つ。入母屋造を基本とした複雑な銅板葺屋根を架け，２階部は楼閣風になる。全体に上質の材を吟味し，室内は数寄屋風で伝統的な造形を巧みに用い丁寧に仕上げる。外観内部とも充実した意匠の和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002897"},{"id":"00013700","register_sub_id":"101","register_pk":"507735","name":"嶋﨑家住宅主屋","kana":"しまざきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県海老名市上郷一丁目224-2他","lat":35.45222389,"lng":139.380985,"geo_status":"db","era":"明治後期／大正15年・昭和50年・同57年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"14 － 297","desc":"相模川左岸の集落の敷地に東面して建つ。入母屋造銅板葺の周囲に下屋を廻らす。左土間形式で、床上部は県央地域の伝統的な民家にみられる食違六間取形式とし、正面に腰を市松模様としたガラス戸を建てる。軸部重厚で施工も洗練された、近代の上質な民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013700"},{"id":"00013701","register_sub_id":"101","register_pk":"507736","name":"嶋﨑家住宅離れ","kana":"しまざきけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県海老名市上郷一丁目223-2他","lat":35.45428333,"lng":139.38049722,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"14 － 298","desc":"主屋の北東側に廊下を介して東西棟で建つ。平屋建、入母屋造銅板葺で下屋を廻らす。八畳二室の三方に縁を設けてガラス戸を建てる。天井は一畳大の天井板八枚を組合わせて天井縁で区画するもので目を引く。四方柾の杉材など材料を吟味し、意匠を凝らした離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013701"},{"id":"00002622","register_sub_id":"101","register_pk":"103612","name":"正眼寺本堂（旧今村繁三別荘）","kana":"しょうげんじほんどう（きゅういまむらしげぞうべっそう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本562","lat":35.22848496,"lng":139.1001178,"geo_status":"db","era":"明治37頃／昭和7移築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"14 － 0066","desc":"町中部，旧東海道の南側の傾斜地にある。正方形平面の入母屋造とし，外装を真壁・一部押縁下見，三方に一間幅の畳廊下と半間幅の縁を設ける開放的な造りとし，内部の欄間に意匠を凝らす。本格的書院造の，別荘建築に相応しい外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002622"},{"id":"00002373","register_sub_id":"101","register_pk":"103363","name":"神山荘（旧藤山雷太別荘）","kana":"しんざんそう（きゅうふじやまらいたべっそう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1300-92","lat":35.247761,"lng":139.042892,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、茅葺、建築面積431㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"14 － 0057","desc":"箱根登山鉄道ケーブル線公園上駅南方に位置する別荘建築で，軽快な玄関の右手に緑色瓦，洋館仕立ての食堂・応接室棟，左手に茅葺の「中の間」棟と「上の間」棟を配する。地形の高低差を利用し，中庭を巧みに配置した変化に富んだ建築構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002373"},{"id":"00011278","register_sub_id":"101","register_pk":"209114","name":"神霊教鎌倉錬成場練塀","kana":"しんれいきょうかまくられんせいじょうねりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県鎌倉市長谷三丁目598","lat":35.315398,"lng":139.53352,"geo_status":"db","era":"昭和31頃","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"土塀、瓦葺、延長16m","structure_material":"土塀","registered":"2016.11.29(平成28.11.29)","register_no":"14－0225","desc":"待合の背面側から矩折れに延びる練塀。延長一六メートルで、玉石の布基礎上に土と平瓦を交互に九段積み、頂部には瓦葺の小屋根を造る。高さは七〇センチメートル強である。設計図より増築部茶室、待合と一体に作られたことが明らかで、一連の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011278"},{"id":"00011277","register_sub_id":"101","register_pk":"209113","name":"神霊教鎌倉錬成場待合","kana":"しんれいきょうかまくられんせいじょうまちあい","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県鎌倉市長谷三丁目598","lat":35.315406,"lng":139.533493,"geo_status":"db","era":"昭和31頃","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.6㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"14－0224","desc":"別荘の所有が九鬼家に移った後に建てられたもの。木造平屋建、切妻造銅板一文字葺で、主屋の北東端に増築された茶室の東に建つ。柱等には杉丸太を用い、壁は土壁腰部杉皮張とし、庭園景観を形成する。内部は棟通前後で二室に分け、南に腰掛、北に雪隠を配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011277"},{"id":"00011279","register_sub_id":"101","register_pk":"209115","name":"神霊教鎌倉錬成場門","kana":"しんれいきょうかまくられんせいじょうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県鎌倉市長谷三丁目607","lat":35.315222,"lng":139.532905,"geo_status":"db","era":"昭和31頃","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造、銅板葺、間口1.8m","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"14－0226","desc":"主屋西方の坂下に建つ。一間腕木門で、銅板一文字葺の屋根をかけ、控柱を立てる。垂木は磨き丸太を疎らに配する。桁と棟木は節勝ちの磨き丸太を用い、侘びた風情を醸し出している。主屋・茶室へと導く中門にあたり、敷地景観を特徴付ける門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011279"},{"id":"00011276","register_sub_id":"101","register_pk":"209112","name":"神霊教鎌倉錬成場霊源閣","kana":"しんれいきょうかまくられんせいじょうれいげんかく","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県鎌倉市長谷三丁目598","lat":35.315192,"lng":139.533182,"geo_status":"db","era":"大正7／昭和31増築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積477㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"14－0223","desc":"山本条太郎が別荘として建てたもの。南端の客間から北側二方に諸室を連ね、西寄りには居間、台所等、東寄りには洋室、茶室等を配する。居間は崖上に張出し表玄関は崖下に配し階段で結ぶ。表千家残月亭を意識した意匠を見せるなど、上質な近代数寄屋建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011276"},{"id":"00016659","register_sub_id":"101","register_pk":"579143","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県逗子市久木三丁目291","lat":35.301029,"lng":139.573767,"geo_status":"db","era":"昭和23年頃／昭和30年頃増築、平成15年頃改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積206㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"14 - 0371","desc":"昭和戦前期に集落移転で造成された逗子駅北側の住宅地にある主屋。東面して建つ寄棟造桟瓦葺で、玄関脇に和風の客間を設け、中廊下の南に座敷を並べ、奥に離れを配する。差鴨居や大黒柱に移転前の旧材を転用。床廻りなど、銘木を用いた良質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016659"},{"id":"00014150","register_sub_id":"101","register_pk":"508780","name":"須藤家住宅主屋","kana":"すどうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県逗子市新宿二丁目2132","lat":35.29452222,"lng":139.57134167,"geo_status":"db","era":"昭和7年／同41年・平成12年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、スレート葺、建築面積138㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"14-0308","desc":"逗子海岸近くに位置する住宅。東を玄関とし、内部は中廊下平面で、玄関脇に洋室の応接、南面中央に続き座敷と広縁、南西に洋室の書斎を配し、庭を臨む。二階は洋室と和室を東西に並べる。軒の出を押さえ、窓庇を水平に連続させて意匠平明な昭和前期の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014150"},{"id":"00014151","register_sub_id":"101","register_pk":"508781","name":"須藤家住宅旧ボイラー室","kana":"すどうけじゅうたくきゅうぼいらーしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県逗子市新宿二丁目2132","lat":35.29458889,"lng":139.57136389,"geo_status":"db","era":"昭和21年頃／同27年改修","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積8.8㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"14-0309","desc":"主屋北側に位置するＧＨＱが建築した旧ボイラー室。切妻造鉄板葺平入の平屋建東西棟で、南に戸口、三面に高窓を開け、外壁下見板張とする。内部はかつて西にボイラー、貯湯槽、東に石炭庫を配した。現在は一室の倉庫として利用する。昭和戦後の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014151"},{"id":"00004761","register_sub_id":"101","register_pk":"105751","name":"清閑亭","kana":"せいかんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市南町1-5-73","lat":35.248253,"lng":139.152512,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋一部2階建、瓦葺、建築面積276㎡","structure_material":"木造平屋一部2階建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0118","desc":"小田原城址南側の丘陵にたつ。木造平屋建，入母屋造，桟瓦葺の主屋部分に，木造２階建の東棟を接続し，全体として東西に広がる雁行状の平面をとる。南面全体に，銅板葺の庇を廻らすことで，外観に連続性をもたせ，内部は数寄屋風の丁寧なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004761"},{"id":"00002224","register_sub_id":"101","register_pk":"103214","name":"関戸家住宅穀蔵","kana":"せきどけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県横浜市青葉区美しが丘西2-40-8","lat":35.59004826,"lng":139.53154809,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0052","desc":"主屋東端のもと馬屋の東南前方に位置し，主屋とは棟をやや振って建つ。桁行４間，梁行２間規模の２階建土蔵で，西妻面に土庇を付けて蔵前を設け，切妻造，桟瓦葺の置屋根を載せる。丁寧な造りの穀蔵で，現在は文庫蔵と同様に腰を石造風に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002224"},{"id":"00002222","register_sub_id":"101","register_pk":"103212","name":"関戸家住宅主屋","kana":"せきどけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県横浜市青葉区美しが丘西2-40-8","lat":35.59009717,"lng":139.53131783,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、亜鉛メッキ鋼板葺、建築面積304㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0050","desc":"横浜・川崎の市境近くに位置する旧保木村の名家の住宅で，桁行１４間と横浜市内では最大級規模の民家。寄棟造，もと茅葺で，内部は東側に土間を置いた六間取形式で，土間に接して馬屋を内部に取りこむ。横浜郊外における農村の原風景を伝えることで貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002222"},{"id":"00002223","register_sub_id":"101","register_pk":"103213","name":"関戸家住宅文庫蔵","kana":"せきどけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県横浜市青葉区美しが丘西2-40-15","lat":35.59007472,"lng":139.53108146,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"土蔵造2階建、亜鉛メッキ鋼板葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0051","desc":"主屋の西方に位置する。桁行３間，梁行２間規模の２階建土蔵で，東西棟，切妻造の置屋根を載せる。外装は，開口部回りを除いて，現在は目地を切って石造風に見せる。東妻面に蔵前を設け，主屋寄りに隠居所と伝える床付８畳間を備えている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002223"},{"id":"00008427","register_sub_id":"101","register_pk":"134823","name":"髙﨑家住宅主屋","kana":"たかさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市山ノ内字藤源治942-1","lat":35.33719355,"lng":139.54286271,"geo_status":"db","era":"昭和5年／平成19年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、金属板葺、建築面積129㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"14 － 0167","desc":"山ノ内の住宅地に位置する。南北棟の切妻造桟瓦葺。木造二階建、建築面積一二九平方メートル。外壁は竪羽目板張。東西に中廊下を通し、東端に玄関、南面に洋間や座敷茶の間などを配する。切妻造の大きな妻面に、下屋と庇を二段に付けて、明快な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008427"},{"id":"00014145","register_sub_id":"101","register_pk":"508775","name":"髙橋家住宅主屋","kana":"たかはしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横須賀市本町二丁目10","lat":35.28144444,"lng":139.66428056,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積124㎡","structure_material":"木造平屋一部2階建","registered":"2022.02.17(令和4.02.17)","register_no":"14-0303","desc":"どぶ板通り南の丘陵に西面する米穀商の住宅。道に面して入母屋造の玄関を付す和館の北に、切妻造妻入フランス瓦葺の洋館を接続する。内部はＬ字形平面で玄関から東へ片廊下を延ばし、北に座敷など和室三室を並べる。和洋の意匠を並置し横須賀の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014145"},{"id":"00013238","register_sub_id":"101","register_pk":"366227","name":"田中・大野邸主屋","kana":"たなか・おおのていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市扇ガ谷二丁目255","lat":35.32754167,"lng":139.55300556,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"14 － 0279","desc":"谷筋奥の敷地で南面し、外壁は下見板張で上下窓を並べ、フランス瓦を葺くなど洋風でまとめる。平面は一六坪の広い居間を中心としたＨ字形で、東に書斎や寝室、西に応接間、食堂、水回りを配する。戦前の鎌倉市における閑静な住環境を伝える瀟洒な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013238"},{"id":"00007980","register_sub_id":"101","register_pk":"128812","name":"田畑家住宅主屋","kana":"たばたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市神奈川区白幡上町93","lat":35.48821782,"lng":139.6311606,"geo_status":"db","era":"昭和7／昭和中期・昭和後期改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺及びスレート葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0156","desc":"北と東に接道した角の敷地の南寄りに建つ。木造平屋建、南北棟の寄棟造で桟瓦葺の和館部と、東西棟の切妻造スレート葺の洋館部からなる。建築面積１０７㎡。洋館部のドイツ壁仕上げの妻壁と、入母屋の妻を見せる真壁造の玄関が好対照をなす郊外住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007980"},{"id":"00008426","register_sub_id":"101","register_pk":"134822","name":"田丸家住宅主屋","kana":"たまるけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県鎌倉市扇ガ谷2-254-1","lat":35.32753104,"lng":139.55299728,"geo_status":"db","era":"大正7年／昭和3年・昭和35年・昭和45年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋一部2階建、スレート葺、建築面積149㎡","structure_material":"木造平屋一部2階建","registered":"2011.01.26(平成23.01.26)","register_no":"14 － 0166","desc":"扇ガ谷の木立の中に占める敷地の中央に建つ。木造平屋建、建築面積一四九平方メートル。南北棟を中心に東西棟を十字に架ける複雑な切妻屋根でスレート葺とする。外壁は下見板張。西面の玄関から中廊下を通し、南に応接室や居間などを配する。簡素で軽快な洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008426"},{"id":"00002898","register_sub_id":"101","register_pk":"103888","name":"千世倭樓主屋","kana":"ちよわろうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県小田原市風祭50","lat":35.24527,"lng":139.130066,"geo_status":"db","era":"明治中期／平成12移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、銅板葺、建築面積318㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"14 － 0072","desc":"平鹿郡地方で江戸末期から明治初期頃に広まった曲屋形式を継承した住宅。木造一部２階建で，入母屋造の屋根を架け，豪壮な外観とする。直線状の梁を用いた梁組，貫と束を多用した軸組や小屋組，床など優れた飾りをもつ座敷など，近代の造形が顕著にみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002898"},{"id":"00002899","register_sub_id":"101","register_pk":"103889","name":"千世倭樓土蔵","kana":"ちよわろうどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県小田原市風祭50","lat":35.24544059,"lng":139.13022073,"geo_status":"db","era":"明治中期／平成12移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積81㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"14 － 0073","desc":"主屋の台所脇の土間側に連続して建つ。桁行７間，梁間３間半の規模を有する木造・２階建，切妻造・桟瓦葺，妻入で，戸口に重厚なつくりの観音扉を設ける。軸組は狭い間隔で柱を密に立て，成の高い貫で強固に固め，木部を漆塗とするなど，地方的特色をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002899"},{"id":"00010933","register_sub_id":"101","register_pk":"208904","name":"月山堂滴水庵大門","kana":"つきやまどうてきすいあんおおもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県藤沢市辻堂太平台一丁目10-25","lat":35.329555,"lng":139.461184,"geo_status":"db","era":"昭和35頃","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造、瓦葺一部銅板葺、間口4.6m","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0206","desc":"敷地北東の道路から引込んだ露地に建つ。間口四・五メートルの切妻造桟瓦葺で軒先に銅板を葺き廻す。中央の門口に板戸を引分け、右手に供待を囲み、格子窓をあける。軸部や軒の大半を丸太とし、腰に栗ナグリ材を詰打ちする。草庵の正門としての風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010933"},{"id":"00010931","register_sub_id":"101","register_pk":"208902","name":"月山堂滴水庵主屋","kana":"つきやまどうてきすいあんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市辻堂太平台一丁目10-25","lat":35.329579,"lng":139.461071,"geo_status":"db","era":"明治後期／昭和35移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0204","desc":"起伏に富む広い敷地内で湧水池に臨み、主体部は宝形造桟瓦葺。九畳主室の庭側に矩の手に一間幅の広縁をまわし、玄関や台所を備え、北隅に三畳台目茶室を張出す。全体的に木割が細く、庭に対して開放的な構成で、建具等の造作も繊細で上質な数寄屋建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010931"},{"id":"00010932","register_sub_id":"101","register_pk":"208903","name":"月山堂滴水庵待合","kana":"つきやまどうてきすいあんまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県藤沢市辻堂太平台一丁目10-25","lat":35.32942778,"lng":139.46106389,"geo_status":"db","era":"昭和35頃","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0205","desc":"主屋の南東に西面し、桁行一・八メートル、招き屋根風の切妻造銅板葺である。軸部や軒の主要部材に丸太を使い、特に前面柱や梁に自然の曲り材をそのまま組む。壁は中塗仕上げで、背面に下地窓を穿つ。奇想に富む数寄屋の構成で、庭園の重要な構成要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010932"},{"id":"00005939","register_sub_id":"101","register_pk":"106924","name":"角田家住宅石垣","kana":"つのだけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市栄区公田町2306","lat":35.34950306,"lng":139.55903806,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造、延長40m","structure_material":"石造","registered":"2006.11.29(平成18.11.29)","register_no":"14 － 0136","desc":"敷地の東辺をなす石垣で，谷戸の下手側にあたり，当家に至る道路の擁壁である。当地に産した砂岩系の鎌倉石を整層切石積とし，延長４０ｍ。見付高さ３０ｃｍの石を９石まで積み，上端を笠石で押さえる。上部は生垣とし良好な宅地景観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005939"},{"id":"00005937","register_sub_id":"101","register_pk":"106922","name":"角田家住宅主屋","kana":"つのだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市栄区公田町2306","lat":35.34943964,"lng":139.55875109,"geo_status":"db","era":"大正2頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"14 － 0134","desc":"丘陵中腹，谷戸の上端に敷地を構える桁行８間，梁間４間のつし２階建。瓦葺屋根の軒は出桁造とする。東を土間，西を整形六間取の居室とする。居室南面を下屋として縁を通し，戸袋を銅板張で飾る。土間後半と背面水回りを改修。農家系近代和風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005937"},{"id":"00005938","register_sub_id":"101","register_pk":"106923","name":"角田家住宅道具蔵","kana":"つのだけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県横浜市栄区公田町2306","lat":35.34936073,"lng":139.55868773,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"14 － 0135","desc":"主屋の西面南端に接続する土蔵造２階建。主屋の南西８畳室の西側を蔵前とし，両開塗戸を開く。切妻造，桟瓦葺の東西棟で，小屋組は梁に架けた牛梁に束立で棟木を載せる。外壁は黒漆喰塗で，２階南面に塗戸付の窓を開く。重厚感のある外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005938"},{"id":"00010428","register_sub_id":"101","register_pk":"202566","name":"藤間家住宅主屋","kana":"とうまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県茅ヶ崎市柳島2-282-イ","lat":35.325087,"lng":139.380149,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"14 － 0192","desc":"敷地中央に東面する。洋間を玄関南脇のみに配するが、北脇の和室を含む東立面全体を下見板張の洋風意匠で統一する。その他は簓子下見板張として和洋の意匠を対比的に採用する。平面は中廊下の前後に居室を並べる。設計者西村伊作の作風の一端を示す近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010428"},{"id":"00014580","register_sub_id":"101","register_pk":"515122","name":"中嶋家住宅（旧ピゴット邸）主屋","kana":"なかじまけじゅうたく（きゅうぴごっとてい）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市中区山手町69-7","lat":35.43650833,"lng":139.65111667,"geo_status":"db","era":"大正14年／昭和55年・平成6年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積102㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0329","desc":"旧山手居留地に建つ大きな切妻屋根と太い円柱の玄関ポーチが特徴の洋館。内部はベイウィンドウ付食堂を中心に諸室を配置、応接間と食堂、居間に暖炉を置く。二階は屋根裏部屋の個室を設け、元は南面をサンルームとした。震災後の外国人住宅として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014580"},{"id":"00002225","register_sub_id":"101","register_pk":"103215","name":"長島孝一家住宅主屋","kana":"ながしまこういちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県逗子市新宿1-5-14","lat":35.290459,"lng":139.574722,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"14 － 0053","desc":"逗子で最初に別荘地が拓かれた田越川界隈に建つ。長島鷲太郎の葉山別邸として建設。木造平屋建の和風別荘で，南面に起り破風の玄関庇を付け，東面に座敷と広縁，北に離れを配するが，震災後９０度振って復旧されたと伝える。数少ない海浜別荘遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002225"},{"id":"00005262","register_sub_id":"101","register_pk":"106250","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県相模原市南区磯部1734","lat":35.50712741,"lng":139.39070504,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、金属板葺、建築面積231㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"14 － 0120","desc":"木造２階建，寄棟造，金属板葺で，１階を整形四間取を基本とし，西側に式台玄関を設け，外壁も和風の要素でまとめるが，２階は外壁を海鼠壁とし，軒を曲線の白漆喰で塗り込め，正面に縦長の窓を配する。鎌倉大工の石井甚五郎の手による初期の擬洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005262"},{"id":"00014146","register_sub_id":"101","register_pk":"508776","name":"西﨑家住宅(船越町洋館付き住宅)主屋","kana":"にしざきけじゅうたく（ふなこしちょうようかんつきじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横須賀市船越町三丁目31-5他","lat":35.29878889,"lng":139.62006111,"geo_status":"db","era":"昭和13年／同47年・令和元年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"14-0304","desc":"長浦湾を見下ろす丘陵に南面する元御用商人の住宅。東半を洋館、西半を和館とし、正面中央に入母屋造の玄関を突出する。洋館はスティックスタイルとし、屋根は半切妻とする。和館は続き座敷を配し、南西に縁を巡らす。高台にあって地域の景観を形成する住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014146"},{"id":"00016658","register_sub_id":"101","register_pk":"579142","name":"新川家住宅主屋","kana":"にっかわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市旭区今宿南町2102","lat":35.481709,"lng":139.523256,"geo_status":"db","era":"明治中期／昭和10年頃増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、茅葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"14 - 0370","desc":"八王子街道南方の丘陵斜面に東面して建つ農家の主屋。入母屋造平入茅葺で、軒をせがいにつくり、内部は北側を土間とした整形四間取。小屋内に二層の床を張って蚕室とし、両妻に通風や採光用の窓を開ける。明治期に当地に数多く建てられた養蚕農家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016658"},{"id":"00002533","register_sub_id":"101","register_pk":"103523","name":"白雲洞茶苑対字斎","kana":"はくうんどうちゃえんついじさい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1300-69","lat":35.249149,"lng":139.045395,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、柿葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0065","desc":"白雲洞の東に建ち，寄付を介して渡廊下で連絡する。炉を切った主室８畳と水屋を備えた控え４畳の座敷の東及び南に矩折れに広縁を回した平面で，東寄り傾斜地の部分は掛造りとし，変化に富んだ外観を造る。山荘が原三渓に譲渡された後に建築されたといわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002533"},{"id":"00002529","register_sub_id":"101","register_pk":"103519","name":"白雲洞茶苑白雲洞","kana":"はくうんどうちゃえんはくうんどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1300-69","lat":35.24911952,"lng":139.04516822,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、茅葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0061","desc":"三井物産総帥益田孝が営んだ山荘の茶室の一つ。６畳に手前座を付した主室，４畳の次の間，水屋などからなり，主室には囲炉裏を切る異例の構えとする。寄棟造，茅葺で田舎屋風の外観を呈し，室内では古材を数多く用い，内外とも野趣あふれた独特の意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002529"},{"id":"00002532","register_sub_id":"101","register_pk":"103522","name":"白雲洞茶苑白鹿湯","kana":"はくうんどうちゃえんはくろくとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1300-69","lat":35.24899952,"lng":139.04479392,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、柿葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0064","desc":"寄付東の一段低い位置に築かれた浴室。大岩を巧みに利用し上屋をかけて造られた建物で，寄付からは急勾配の階段で連絡する。太い丸太を組んだ軸組に外壁，屋根下地とも丸太を密に打ち並べた独特の造りで，山荘の浴室にふさわしい素朴で雅趣に富む意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002532"},{"id":"00002530","register_sub_id":"101","register_pk":"103520","name":"白雲洞茶苑不染庵","kana":"はくうんどうちゃえんふせんあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1300-69","lat":35.249073,"lng":139.04488265,"geo_status":"db","era":"大正5頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、茅葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0062","desc":"白雲洞の西に独立して建つ寄棟造，茅葺の茶室。２畳台目の小間とともに４畳半の寄付，水屋を備え，前面に深い土庇を付す。?丸太を多用し，竹垂木の駆込み天井とするなど，草庵風の侘びた意匠になる。設計は，数寄者・工匠として名高い仰木魯堂と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002530"},{"id":"00002531","register_sub_id":"101","register_pk":"103521","name":"白雲洞茶苑寄付","kana":"はくうんどうちゃえんよりつき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅1300-69","lat":35.24924582,"lng":139.04516326,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、柿葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0063","desc":"白雲洞などに至る苑路の最も手前にあり，これらの茶室の寄付となる建物で，４畳半の南東隅を欠いた変形平面の座敷と２畳の次の間からなる。筋違に欠いた南東部分は，湾曲した丸太の桁を用い，扇状に小丸太の垂木を配して化粧軒を造る巧緻で斬新な意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002531"},{"id":"00002527","register_sub_id":"101","register_pk":"103517","name":"箱根小涌園貴賓館（旧藤田平太郎別荘）","kana":"はこねこわきえんきひんかん（きゅうふじたへいたろうべっそう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町二ノ平1297","lat":35.239853,"lng":139.045761,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦一部亜鉛引鉄板及び銅板葺、建築面積860㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0059","desc":"藤田組社長藤田平太郎の別荘として建設された和風建築。北端の玄関から南に座敷を並べ，この西に中庭を挟んでサービス部分を配する。座敷の瀟洒な意匠とともに，各室を廊下で繋ぐ巧みな配置に近代的な特徴が見られる。設計・監督は近代の名工の一人今井平七。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002527"},{"id":"00002528","register_sub_id":"101","register_pk":"103518","name":"箱根小涌園迎賓館","kana":"はこねこわきえんげいひんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町二ノ平1297","lat":35.239922,"lng":139.045273,"geo_status":"db","era":"明治8／昭和28移築","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造2階建、鉄板一部桟瓦葺、建築面積396㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"14 － 0060","desc":"県下愛甲郡中津村の名主の家を移築したもの。階上を養蚕のための空間とした２階建，入母屋造，鉄板葺の建物で，屋根の一部を切り上げた養蚕農家独特の外観をもつ。現在，１，２階ともレストランとして活用されているが，座敷の床・棚や欄間はよく保存される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002528"},{"id":"00004733","register_sub_id":"101","register_pk":"105723","name":"箱根湯本ホテル暁亭","kana":"はこねゆもとほてるあかつきてい","category":"住宅","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本茶屋字観音沢182-7","lat":35.22677354,"lng":139.09288343,"geo_status":"db","era":"大正末期／昭和62移築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0119","desc":"箱根湯本の須雲川右岸に位置する別荘建築で，現在レストランとして活用。木造平屋建，桟瓦葺，寄棟造で，たちを低く抑えた端正な外観とする。玄関から正面に延びる廊下の南側に連続して部屋が配される。内部は杉皮張の腰壁などをあしらった数寄屋風のつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004733"},{"id":"00010129","register_sub_id":"101","register_pk":"197962","name":"林家住宅主屋","kana":"はやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市鵠沼桜が岡2-6098-45","lat":35.32798333,"lng":139.47892778,"geo_status":"db","era":"昭和12／昭和33改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋一部2階建、銅板葺一部瓦葺、建築面積218㎡、門付","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"14 － 0190","desc":"急勾配の切妻屋根で、外壁をハーフティンバーとする。内部は、母体となっている古民家の木太い軸部や梁組を現しつつ、間仕切りにテューダーアーチを用い、ステンドグラスを飾るなど巧みに和洋を折衷する。上質な意匠の住宅で、戦前の郊外型住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010129"},{"id":"00012717","register_sub_id":"101","register_pk":"367620","name":"原家住宅主屋","kana":"はらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県平塚市土屋字秦ノ前2842","lat":35.35630194,"lng":139.26357083,"geo_status":"db","era":"明治中期／昭和前期・平成元年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、金属板葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 262","desc":"市北西部の丘陵地にある農家で、主屋は敷地中央に南面して建つ。入母屋造鉄板葺の平屋建で、東に土間、西に広間を取り、奧に前後各2室を配する。広間前面に下屋を出して式台とし、前列上手を座敷とする。県中部の伝統的な民家形式を踏襲した近代の和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012717"},{"id":"00012718","register_sub_id":"101","register_pk":"367621","name":"原家住宅茶室","kana":"はらけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県平塚市土屋字秦ノ前2842-1","lat":35.35630194,"lng":139.26357083,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、茅葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 263","desc":"主屋の西側に建つ。寄棟造茅葺で、北に土間と水屋、南に六畳台目の茶室を配し、南面西半に腰掛待合を付す。茶室は西面を床、南面を貴人口とし、舟底天井を張り、皮付材を多用した野趣に富む意匠でまとめる。近代における上層農家の暮らしの一端を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012718"},{"id":"00012719","register_sub_id":"101","register_pk":"367622","name":"原家住宅土蔵","kana":"はらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県平塚市土屋字秦ノ前2842","lat":35.35630194,"lng":139.26357083,"geo_status":"db","era":"明治中期／平成元年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、金属板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 264","desc":"主屋の東側に西面して建つ。土蔵造二階建、切妻造鋼板葺で、正面中央に扉口を設けて下屋を付す。外壁はモルタル塗の腰洗出し仕上。小屋組はトラスとする。内外に改変があるが、農家の構成に欠かせない附属建物で、県中部の農家の伝統的な屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012719"},{"id":"00012720","register_sub_id":"101","register_pk":"367623","name":"原家住宅旧長屋門","kana":"はらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県平塚市土屋字秦ノ前2871","lat":35.35630194,"lng":139.26357083,"geo_status":"db","era":"江戸後期／昭和21年・平成2年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 265","desc":"寺院から移築したもので、敷地後方の高台に南面して建つ。寄棟造銅板葺の平屋建で、間口13間の中央3間を門口とする。軸部は太めの柱を貫で固め、小屋組は丸太の梁桁を豪壮にかけ渡す。簡素ながら規模雄大なつくりで、近世における長屋門の一形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012720"},{"id":"00010929","register_sub_id":"101","register_pk":"208900","name":"日高家住宅主屋","kana":"ひだかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市腰越五丁目300","lat":35.312758,"lng":139.493802,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、銅板葺、建築面積189㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0202","desc":"一階南面に応接室と座敷など、中廊下の北側に家政部を配し、二階は書斎などとする。一階廊下の通風口、二階のサンルーム、書斎隅部の出窓など住環境への工夫がみられ、また和室に数寄屋意匠、ストーブグリルにアール・ヌーヴォーと、多様な意匠を取入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010929"},{"id":"00010930","register_sub_id":"101","register_pk":"208901","name":"日高家住宅門及び塀","kana":"ひだかけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市腰越五丁目300他","lat":35.3126924,"lng":139.49358972,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"門 石造、間口3.3m 塀 石造、延長21m","structure_material":"門 石造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0203","desc":"敷地西面南端に開く一対の門柱と、北にのびる石塀で、北寄りの主屋勝手口位置に小階段を設ける。いずれも大谷石積で、門柱は六〇センチメートル角の切石を四段積とし、塀は二四センチメートル成で表面をやや目荒しした石を積む。閑静な住宅街に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010930"},{"id":"00013695","register_sub_id":"101","register_pk":"505213","name":"福岡家住宅橐駝庵","kana":"ふくおかけじゅうたくたくだあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市辻堂二丁目1335-2","lat":35.33401111,"lng":139.44705556,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、茅葺一部鉄板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 292","desc":"東半の板間と西半の和室からなる茅葺の離れ。板間は井桁に組む梁組と細竹詰打の下地を現し、和室境に大黒柱を立て民家の土間風とする。和室は竹簀子天井で床柱と落掛に皮付丸太を使う。民家風に数寄屋趣味を加味した風趣ある造りで戦前の別荘の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013695"},{"id":"00000400","register_sub_id":"101","register_pk":"101390","name":"富士屋ホテル菊華荘","kana":"ふじやほてるきっかそう","category":"住宅","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町宮ノ下359","lat":35.24510418,"lng":139.05844522,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積626㎡","structure_material":"木造平屋建","registered":"1997.12.12(平成9.12.12)","register_no":"14 － 0016","desc":"内親王のために建てられた御用邸を別館としたもの。伝統的な書院にならって雁行する配置をとる。良質の材料を用いて過度の装飾を押さえた瀟洒な姿には，当時の優れた技能が発揮されている。設計は宮内省内匠寮で，担当は木子清敬，手中千代太郎，広川兼次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000400"},{"id":"00014467","register_sub_id":"101","register_pk":"512451","name":"本多家住宅（旧中上川家住宅）主屋","kana":"ほんだけじゅうたく（きゅうなかみがわけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町二丁目359-3","lat":35.31961111,"lng":139.55505833,"geo_status":"db","era":"昭和4年／同前期・同29年頃改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積227㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"14 - 0321","desc":"鎌倉市小町の滑川西岸に位置する近代和風住宅。二階建入母屋造桟瓦葺、南西に平屋建の離れを付して全体にＬ字を呈する。北面中央を玄関とし、内部は中廊下を通して和洋室を配し、二階南面にガラス屋根のサンルームを付す。鎌倉の旧別荘地に残る良質な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014467"},{"id":"00014468","register_sub_id":"101","register_pk":"512452","name":"本多家住宅（旧山本家住宅）門及び塀","kana":"ほんだけじゅうたく（きゅうやまもとけじゅうたく）もんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県鎌倉市小町二丁目359-3","lat":35.31971667,"lng":139.55505,"geo_status":"db","era":"昭和29年／平成10年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"門 木造、瓦葺、間口2.0m 塀 木造、瓦葺、総延長15m","structure_material":"門 木造","registered":"2023.02.27(令和5.02.27)","register_no":"14 - 0322","desc":"敷地北面に位置する門及び塀。設計は狩野春一。門は親柱の前後に控え柱を建てて棟木と母屋を受け、屋根は切妻造桟瓦葺。間口は西寄りに二分し、東を両開戸、西を潜戸とする。塀は真壁造とし壁は漆喰仕上げで腰は縦板張。屋敷の表を整える洗練された門と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014468"},{"id":"00014469","register_sub_id":"101","register_pk":"512453","name":"松永記念館無住庵","kana":"まつながきねんかんむじゅうあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県小田原市板橋字秋葉谷津513-7","lat":35.24927222,"lng":139.14115,"geo_status":"db","era":"昭和30年頃／同50年頃・令和2年移築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"14 - 0323","desc":"小田原城西方の松永記念館内に移築した実業家松永安左ヱ門（耳庵）の茶室。入母屋造茅葺型銅板葺で、間取りは東半に土間と板間、西半に茶席と水屋を配し、上部は小屋裏を現す。茶席北東隅に長炉を設け、西南に躙口を開ける。民家古材を用いた数寄者の茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014469"},{"id":"00001769","register_sub_id":"101","register_pk":"102759","name":"松永記念館葉雨庵","kana":"まつながきねんかんよううあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋941-1","lat":35.24870776,"lng":139.14177463,"geo_status":"db","era":"大正13頃／昭和61移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"14 － 0045","desc":"実業家の野崎広太（幻庵）が市内十字町の別邸・自怡荘内に営んだ茶室。設計は幻庵自身で，彼の代表作のひとつ。屋根は桟瓦葺，三畳台目中板入の茶室に，二間四方の水屋が附属する。洗練された意匠をもち，床の間・中板及び中柱による室内構成が優れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001769"},{"id":"00001768","register_sub_id":"101","register_pk":"102758","name":"松永記念館老欅荘（旧松永安左ヱ門邸）","kana":"まつながきねんかんろうきょそう（きゅうまつながやすざえもんてい）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県小田原市板橋513-7","lat":35.249119,"lng":139.141037,"geo_status":"db","era":"昭和21／昭和28増築","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積236㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"14 － 0044","desc":"中部電力の設立者で後に「電力の鬼」と呼ばれた松永安左ヱ門が晩年を過ごした居宅。Ｌ字形に大広間・次の間・東の間を配した平面で，複雑な桟瓦葺屋根をかける。西南の西の間や茶室等は後の増築部分。数寄屋風の意匠を凝らした質の高いつくりになる和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001768"},{"id":"00002022","register_sub_id":"101","register_pk":"103012","name":"三井翠松園（旧三井高達別荘）本館","kana":"みついすいしょうえん（きゅうみついたかみちべっそう）ほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県足柄下郡箱根町小涌谷519-9","lat":35.24002811,"lng":139.04872274,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積449㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"14 － 0047","desc":"箱根小涌園の東隣接地に位置し，東西に細長い敷地に東を正面として宏大な和風別荘を構える。北に玄関を設け，中庭の西側をサービス部，東側を居室部とし，入り組んだ屋根を架ける。意匠は質実簡明で，富士屋ホテルを手がけた河原徳次郎の施工と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002022"},{"id":"00010756","register_sub_id":"101","register_pk":"201591","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町大平台字北畑335","lat":35.238567,"lng":139.073387,"geo_status":"db","era":"昭和5／昭和中期改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積184㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"14 ‐ 0201","desc":"白色の壁面に上下窓と鎧戸を配置した端正な洋風立面をもちつつ、屋根や軒を和風として温泉地の景観との調和が図られる。内部は階段ホールを中心として洋間を配置し、南側に和室を附属する。外国人向けホテル創業家の住宅らしい往時の洋風生活の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010756"},{"id":"00000655","register_sub_id":"101","register_pk":"101645","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県伊勢原市上粕屋862","lat":35.4070687,"lng":139.29440705,"geo_status":"db","era":"江戸末期／明治元移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造２階建，鉄板葺，建築面積291㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"14 － 0019","desc":"当地域の自由民権運動の中心的役割を担った旧家で，六間取りの民家であるが，二階に二間続きの数寄屋風座敷を明治初頭に増築している。欄間の透彫や障子の組子などの造作は精巧で，各室の襖絵なども良好な状態で残り，当家の財力と格式を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000655"},{"id":"00004729","register_sub_id":"101","register_pk":"105719","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市港北区篠原台町12-21","lat":35.492477,"lng":139.627075,"geo_status":"db","era":"昭和13頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積90㎡","structure_material":"木造平屋一部2階建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0110","desc":"敷地の中央北寄りに建つ木造平屋建の和風住宅で，屋根は桟瓦葺である。入母屋屋根の玄関脇に洋瓦葺半切妻屋根の洋風応接間を突出する。内部は玄関奥に付書院の床飾りをもつ８畳座敷に次の間６畳が続き，縁を巡らせる。私鉄沿線住宅地に建つ一間洋館付住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004729"},{"id":"00000656","register_sub_id":"101","register_pk":"101646","name":"山口家住宅離れ","kana":"やまぐちけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県伊勢原市上粕屋862","lat":35.40721303,"lng":139.29438976,"geo_status":"db","era":"江戸末期／明治元移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建，鉄板葺，建築面積96㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"14 － 0020","desc":"関東大震災後の改築部分。主屋の北端から雁行形に増築され，奥に２階建の土蔵を付ける。８畳と６畳の二間から成り，三方に縁側を回す。寄棟波形鉄板葺で，片方の棟を土蔵の妻面に突きつけ，南と東面の縁側は下屋の扱いとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000656"},{"id":"00014470","register_sub_id":"101","register_pk":"512454","name":"山口蓬春記念館（旧山口蓬春邸）主屋","kana":"やまぐちほうしゅんきねんかん（きゅうやまぐちほうしゅんてい）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県三浦郡葉山町一色字三ケ岡2320-1他","lat":35.266475,"lng":139.57592222,"geo_status":"db","era":"大正前期／昭和32年・同40年増築、平成3年・同25年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋一部2階建、瓦葺、建築面積246㎡","structure_material":"木造平屋一部2階建","registered":"2023.02.27(令和5.02.27)","register_no":"14 - 0324","desc":"一色海岸北の丘陵に位置する日本画家の自邸。寄棟造桟瓦葺の東西棟平屋建、南東隅を二階建とし、南と東に張り出す増築の茶の間棟・風呂棟は吉田五十八の設計。繊細な建具や床の納まりで和室とベランダの連続性を実現する吉田らしさを加味した近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014470"},{"id":"00014471","register_sub_id":"101","register_pk":"512455","name":"山口蓬春記念館（旧山口蓬春邸）画室","kana":"やまぐちほうしゅんきねんかん（きゅうやまぐちほうしゅんてい）がしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県三浦郡葉山町一色字三ケ岡2320-1他","lat":35.26645278,"lng":139.57567222,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"14 - 0325","desc":"主屋西に位置する画室。設計は吉田五十八。切妻造桟瓦葺の起屋根で周囲に銅板庇を付す。室内は大壁とし細かな線を排除し、床を一段下げた南のベランダ境には天井高いっぱいの引込み障子を建てる。蓬春と大学同窓の吉田五十八との共作による近代数寄屋の画室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014471"},{"id":"00000960","register_sub_id":"101","register_pk":"101950","name":"吉池旅館別荘（旧岩崎弥之助別邸和館）","kana":"よしいけりょかんべっそう(きゅういわさきやのすけべっていわかん)","category":"住宅","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本597-1","lat":35.2299987,"lng":139.09917163,"geo_status":"db","era":"明治37頃","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積371㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"14 － 0025","desc":"明治期箱根の和風別荘建築を代表する遺構のひとつ。設計は，京都出身で，岩崎家建築技師の清水仁三郎。入母屋桟瓦葺，銅板葺四方下屋付きの数寄屋を雁行させる建築構成を基調とし，おおむね当初の姿を伝えている。かってはコンドル設計の洋館が隣接していた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000960"},{"id":"00011660","register_sub_id":"101","register_pk":"210676","name":"吉岡家住宅主屋","kana":"よしおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市由比ガ浜一丁目121-2","lat":35.316013,"lng":139.547337,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、スレート葺、建築面積88㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"14-0232","desc":"ラジオ商店舗の別館としての利用も意図した住宅建築。木造二階建、スレート葺で、一階には洋風のアトリエ、サンルームなどを配し、二階は和風でまとめる。一階のステンドグラス、二階の床廻りあるいは天井など、さまざまな意匠を織り交ぜた特徴的な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011660"},{"id":"00009738","register_sub_id":"101","register_pk":"195567","name":"檑亭山門","kana":"らいていさんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県鎌倉市鎌倉山3-1815-5","lat":35.31689724,"lng":139.51500841,"geo_status":"db","era":"明和7／昭和6移築","year":1770,"year_source":"db","year_min":1770,"year_max":1770,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0178","desc":"本館の北方、東側道路に面して建つ間口三・二メートルの四脚門で、切妻造桟瓦葺である。円柱の本柱間を冠木で繋いで絵様虹梁を重ね、控柱は頭貫と台輪で固める。皿斗付大斗の三斗を詰組とし、軒は二軒繁垂木、妻飾は虹梁蟇股である。禅宗様意匠を取入れた四脚門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009738"},{"id":"00009737","register_sub_id":"101","register_pk":"195566","name":"檑亭本館","kana":"らいていほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市鎌倉山3-1815-5他","lat":35.31647679,"lng":139.51519877,"geo_status":"db","era":"昭和4／昭和5増築・昭和44改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造及び鉄筋コンクリート造平屋建一部地階付、瓦葺、建築面積264㎡","structure_material":"木造及び鉄筋コンクリート造平屋建一部地階付","registered":"2013.12.24(平成25.12.24)","register_no":"14 － 0177","desc":"鎌倉山の敷地に建つ。一階は民家の古材を用いた木造で、南面の和室三室に縁を廻らせ、西端の洋室にステンドグラスを飾る。地階は鉄筋コンクリート造で、開放的な土間を中心とする。一階西端に突出する玄関部は寺院玄関を移築。和洋の意匠を混交させた別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009737"},{"id":"00005778","register_sub_id":"101","register_pk":"106766","name":"和智家住宅主屋","kana":"わちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県相模原市緑区名倉字横畑3788","lat":35.60193054,"lng":139.13629956,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、鉄板葺、建築面積196㎡","structure_material":"木造平屋一部2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0133","desc":"敷地奥寄りに南面する。木造平屋建，一部２階，東面切妻造，西面入母屋造，桟瓦形鉄板葺とする。正面中央に切妻屋根の式台玄関を付ける。内部は前後２列に８室を配し，座敷部は長押を用いて床の間を備え書院造風とする。幕末期の大規模な民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005778"},{"id":"00002900","register_sub_id":"101","register_pk":"103890","name":"飯田家住宅土蔵","kana":"いいだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西区内野町1088","lat":37.85597726,"lng":138.93630605,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0118","desc":"新潟市内の西方に所在する商家の土蔵で，主屋等の後方，路地沿に建つ。木造・２階建，切妻造・桟瓦葺，庇付，平入の土蔵造で，戸口に観音扉を用いる。棟札から地元の棟梁の作と判明するが，１尺毎に柱を立てて，その間に金物を用いた壁構造に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002900"},{"id":"00013075","register_sub_id":"101","register_pk":"368251","name":"五十嵐家住宅門","kana":"いからしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県阿賀野市金屋字川端342-1","lat":37.828475,"lng":139.26241667,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0516","desc":"主屋の南方に位置する。間口二・六メートルの一間一戸薬医門で、切妻造桟瓦葺。本柱の頭貫上に冠木を渡し、梁を三丁架けて桁を受け、梁上の束で棟木を受ける。天井は竿縁天井で、妻壁は漆喰塗とする。豪農の住宅の風格ある表構えを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013075"},{"id":"00014788","register_sub_id":"101","register_pk":"519046","name":"怡顔亭","kana":"いがんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県上越市大字戸野目字寺畑482他","lat":37.12235833,"lng":138.27596944,"geo_status":"db","era":"明治45年／昭和中期改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積257㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0592","desc":"戸野目の地主が建てた客殿。敷地中央に南面する入母屋造平入桟瓦葺で正面に銅板葺唐破風玄関を付す。間取りは中廊下の南に2室、北に3室並べ、北面に土縁を付す。南東座敷は床脇に組子の窓や櫛形の天袋など繊細な意匠。大振りな玄関が目を惹く近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014788"},{"id":"00011926","register_sub_id":"101","register_pk":"210933","name":"石井家住宅御小休所御門","kana":"いしいけじゅうたくごしょうきゅうしょごもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県阿賀野市東町1505-1","lat":37.797161,"lng":139.199048,"geo_status":"db","era":"明治11年","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造、銅板葺、間口2.7m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"15-468","desc":"明治天皇の北陸御巡幸の御小休所への立ち寄りのため敷地西面の塀に設けられた門。間口二・七メートルの腕木門であるが、木太い柱を屋根上まで立て登らせ、腕木や疎垂木は繊細で銅板葺の屋根を架ける。行幸のための格式を備え、屋敷地を画す門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011926"},{"id":"00011925","register_sub_id":"101","register_pk":"210932","name":"石井家住宅主屋","kana":"いしいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県阿賀野市東町1505-1","lat":37.797184,"lng":139.19925,"geo_status":"db","era":"天保9年（1838）頃／明治11年・昭和51年改修","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造2階建、瓦葺、314㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-467","desc":"藍の専売と酒造業を営んだ家。通り土間の東に御供部屋や女中部屋を配し、西に帳場やチャノマ、ダイドコロ等と座敷や仏間等を二列で並べる。座敷は御小休所のために玉座や御次間、上段ノ間から成り、玉座は内部は天井までも紙貼とし往時のまま残されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011925"},{"id":"00006650","register_sub_id":"101","register_pk":"107633","name":"石本家住宅表門及び袖塀","kana":"いしもとけじゅうたくおもてもんおよびそでべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市江南区東本町5-322他","lat":37.8694207,"lng":139.10956539,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"表門 木造、銅板葺、間口2.1m、袖塀 鉄筋コンクリート造、延長11m","structure_material":"表門 木造","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0267","desc":"長屋門の南、敷地南辺に位置する。表門は切妻造銅板葺の腕木門で引違格子戸をたて、まぐさ上部を吹き放す軽快な意匠。袖塀は表門の東西に延び、コンクリート造で、腰壁を段をつける重厚な構え。両者の対照的な意匠が屋敷の表構えのアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006650"},{"id":"00006653","register_sub_id":"101","register_pk":"107636","name":"石本家住宅廻廊","kana":"いしもとけじゅうたくかいろう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区東本町5-322他","lat":37.86945314,"lng":139.1097688,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長43m、面積49㎡","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0269","desc":"主屋南側の中庭を凹の字状に囲む。幅１間、切妻造桟瓦葺とし、中庭側を吹放ちとする。南面及び西面は軒までを塗り込める大壁で、微妙に凹凸を付けた黒漆喰仕上げ、腰壁を石貼風のモルタル仕上げ、軒を白漆喰塗とする。屋敷の表構えに風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006653"},{"id":"00006447","register_sub_id":"101","register_pk":"107430","name":"石本家住宅主屋","kana":"いしもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区東本町5-322他","lat":37.86970096,"lng":139.10959802,"geo_status":"db","era":"明治後期／昭和前期増改築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積352㎡、望楼付","structure_material":"木造2階一部平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0263","desc":"敷地中央北寄りに南面して建つ。土間と２列各３室からなる農家建築に、洋風意匠の応接間や、螺鈿細工を施したラデンノマ、１列３室の２階居室、内部全体に障壁画を描く望楼を昭和前期に増改築した。様々な装飾意匠が室内に施された近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006447"},{"id":"00006649","register_sub_id":"101","register_pk":"107632","name":"石本家住宅長屋門","kana":"いしもとけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区東本町5-322他","lat":37.86944769,"lng":139.10956298,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0266","desc":"主屋の南に南面して建つ、桁行５間梁間２間の平屋建で、寄棟造桟瓦葺とする。中央が石敷の通路で、弁柄塗の両開大戸と両脇に潜戸をたて、東に板敷、西に土間の部屋を配す。外壁は漆喰塗、軒は出桁造の一軒疎垂木。重厚で落ち着いた外観で敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006649"},{"id":"00006651","register_sub_id":"101","register_pk":"107634","name":"石本家住宅横門及び脇廻廊","kana":"いしもとけじゅうたくよこもんおよびわきかいろう","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市江南区東本町5-322他","lat":37.86953052,"lng":139.10960107,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"横門 木造、瓦葺、間口2.1m、脇廻廊 木造、瓦葺、延長12m、面積13㎡","structure_material":"横門 木造","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0268","desc":"主屋南側の前庭と中庭とを区画する。横門は切妻造桟瓦葺の腕木門で、まぐさ上に家紋を象った彫刻を配する。脇廻廊は幅１間、切妻造桟瓦葺で、中庭側を吹放ち、前庭側を漆喰仕上げ真壁で腰杉皮張とする。共に敷地景観に欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006651"},{"id":"00006652","register_sub_id":"101","register_pk":"107635","name":"石本家住宅脇門及び袖塀","kana":"いしもとけじゅうたくわきもんおよびそでべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市江南区東本町5-322他","lat":37.8696613,"lng":139.10978002,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"脇門 木造、銅板葺、間口1.0m、袖塀 木造、銅板葺、延長7.9m","structure_material":"脇門 木造","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0270","desc":"主屋東面南端からコの字型に延びて廻廊北端に至り、中庭の東を区画する。脇門は切妻造銅板葺の腕木門で片開格子戸をたてる。袖塀は延長７．９ｍ、木造で銅板葺。板壁で、中庭側を半割竹で押さえる杉皮張とする。数寄屋風の意匠で中庭空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006652"},{"id":"00002229","register_sub_id":"101","register_pk":"103219","name":"板垣工務店温出保養所主屋","kana":"いたがきこうむてんぬくいでほようじょしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市温出289-1","lat":38.51422981,"lng":139.55242483,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、茅葺、建築面積226㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"15 － 0112","desc":"県北，山北町北部を西流する小俣川沿いの温出地区に位置する。六間取形式の寄棟造，茅葺民家で，農村集落景観の主要な構成要素となる。もと本間家の住宅と伝えるが，現在は新発田市の工務店が取得し，同社の福利厚生施設として整備され有効に活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002229"},{"id":"00002230","register_sub_id":"101","register_pk":"103220","name":"板垣工務店温出保養所倉庫","kana":"いたがきこうむてんぬくいでほようしょそうこ","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市温出289-1","lat":38.51403747,"lng":139.55245654,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"15 － 0113","desc":"主屋の南方に北面して建つ。切妻造，桟瓦葺の平入２階建土蔵で，外部は押縁下見で覆い，北面に桟瓦葺の庇を架け，３戸前とする。内部も３室に仕切り，西端の２階に座敷を設ける。出入口は漆喰塗の観音扉で，まぐさ部に龍などの精巧な鏝絵を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002230"},{"id":"00004740","register_sub_id":"101","register_pk":"105730","name":"伊藤家住宅表門及び内塀","kana":"いとうけじゅうたくおもてもんおよびうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県五泉市羽下122","lat":37.77286945,"lng":139.17379947,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"表門 木造、瓦葺、間口2.1m、内塀 木造、瓦葺、延長21m","structure_material":"表門 木造","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0183","desc":"表門は米蔵北西に南面し，内塀は表門に接続し主屋，米蔵間を南北に仕切る。表門は腕木門形式で，屋根切妻造，桟瓦葺とし，内塀は目板打ち竪板張りで，桟瓦葺屋根を腕木で受ける。簡素だが丁寧な造りで，周囲の建物や庭園とともに風格ある屋敷構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004740"},{"id":"00004738","register_sub_id":"101","register_pk":"105728","name":"伊藤家住宅家財蔵及び計量場","kana":"いとうけじゅうたくかざいぐらおよびけいりょうば","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県五泉市羽下122","lat":37.77273204,"lng":139.17394359,"geo_status":"db","era":"明治9／大正4曳家増築","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造2階一部平屋建、瓦葺、建築面積114㎡","structure_material":"土蔵造2階一部平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0181","desc":"米蔵の東に続いて計量場，家財蔵が一列に並び，これら北面に一連の下屋を付す。家財蔵は２階建，置き屋根の土蔵造で，計量場は南面のみ塗込め，全体を桟瓦葺とする。内外とも丁寧な造りになり，米蔵と一体となって長大な外観をもつ屋敷構えに欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004738"},{"id":"00004737","register_sub_id":"101","register_pk":"105727","name":"伊藤家住宅米蔵","kana":"いとうけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県五泉市羽下122","lat":37.77272555,"lng":139.173828,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積51㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0180","desc":"主屋の南東に北面して建つ。桁行約６間，梁間約２間半，土蔵造，平屋で，切妻造，桟瓦葺の置き屋根をのせる。内部は床を張り，棟通りやや東寄りに独立柱，その南に間柱を立て緩やかに仕切る。切石積基礎を築き，軒に鉢巻，腰に水切を廻す等丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004737"},{"id":"00004736","register_sub_id":"101","register_pk":"105726","name":"伊藤家住宅三階土蔵","kana":"いとうけじゅうたくさんかいどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県五泉市羽下122","lat":37.77259966,"lng":139.17356021,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積89㎡","structure_material":"土蔵造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0179","desc":"敷地南端，通りに接して建つ。桁行６間，梁間３間，土蔵造，３階建，切妻造，置き屋根，桟瓦葺で，戸口のある北面に下屋を付す。側廻りに柱を密に建てた入念な造りで，小屋組の合掌は梁端とボルトで接合する。重厚な外観をもち屋敷の表構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004736"},{"id":"00004880","register_sub_id":"101","register_pk":"105870","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県五泉市羽下122","lat":37.77301555,"lng":139.17364334,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積259㎡","structure_material":"木造平屋一部2階建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0178","desc":"敷地中央北寄りに南面して建つ。矩折れに座敷を配し正面に玄関を突出する主体部を中心に，東に仏間（大正１５），西に風呂場，便所（明治３１）を接続する。増改築を繰り返すが内外とも質の高い丁寧な造りで，まとまりのある外観は広大な屋敷構えの核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004880"},{"id":"00004739","register_sub_id":"101","register_pk":"105729","name":"伊藤家住宅納屋","kana":"いとうけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県五泉市羽下122","lat":37.77260828,"lng":139.17343748,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0182","desc":"三階土蔵西隣に並んで建つ。平屋建，切妻造，桟瓦葺で，内部は東半を土間，西半は床を張り，北面東寄りの出入口部分に下屋を付ける。側廻りは約２尺毎に柱を密に建て，外は漆喰真壁で下部は押縁下見板で囲う。簡素だが屋敷構えにふさわしい丁寧な仕事になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004739"},{"id":"00010277","register_sub_id":"101","register_pk":"199050","name":"今井家住宅主屋","kana":"いまいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県燕市吉田下町5324他","lat":37.692194,"lng":138.878826,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積435㎡","structure_material":"木造平屋一部2階建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0394","desc":"敷地の通り沿いに東面して建つ平屋建妻入で、ミセ空間をもつ主体部と接客間「多聞」を擁する二階建を並べ、前面に雁木を通し、奥に二階建の茶の間や当主の座敷を配する。主体部は北寄りの通り土間沿いに広い畳敷の茶の間が並ぶ。当地域の大地主の豪壮な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010277"},{"id":"00010279","register_sub_id":"101","register_pk":"199052","name":"今井家住宅新座敷","kana":"いまいけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県燕市吉田下町5324他","lat":37.692008,"lng":138.878684,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0396","desc":"西洋館の南に建つ客用座敷。東から玄関の間、中の間、上段の間を並べ、西に茶室四畳半と水屋を付す。北は一間幅の廊下で座敷側半間を畳敷とする。各室にトコなどを設え、上段の間は南面を帳台構風とする。良材を用いた書院座敷で、大地主宅らしい格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010279"},{"id":"00010278","register_sub_id":"101","register_pk":"199051","name":"今井家住宅西洋館","kana":"いまいけじゅうたくせいようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県燕市吉田下町5324","lat":37.692054,"lng":138.878788,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造2階建、瓦葺、建築面積45㎡、火の見櫓付","structure_material":"煉瓦造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0395","desc":"主屋南に隣接する煉瓦造二階建の応接棟。外壁はフランス積で壁頂部と腰に歯飾付のデンティルを廻す。二階にアーチ窓を並べ、屋根上に五角形平面の火の見櫓を上げる。内部は洋室で、シャンデリアや花弁形の中心飾など、明治期らしい重厚華麗な内装をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010278"},{"id":"00010568","register_sub_id":"101","register_pk":"201142","name":"岩﨑家住宅主屋","kana":"いわさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県糸魚川市大字大和川字六反田1183-1","lat":37.052488,"lng":137.890146,"geo_status":"db","era":"寛政2年／昭和51年改修","year":1976,"year_source":"db","year_min":1976,"year_max":1976,"year_label":null,"structure":"木造2階建、瓦葺、建築面積271㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"15－0403","desc":"日本海に近い旧街道沿いの敷地に建つ。東を正面として中央に式台を構え、床上部は北端に続き間座敷、南にヒロマとチャノマを配して、二列三室を喰い違いに並べる。接客用の座敷部は端正な造作の座敷飾りを備え、当地における大型の近世民家の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010568"},{"id":"00010569","register_sub_id":"101","register_pk":"201143","name":"岩﨑家住宅土蔵","kana":"いわさきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県糸魚川市大字大和川字六反田1183-1","lat":37.05253121,"lng":137.88996737,"geo_status":"db","era":"明治前期／昭和51年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"15－0404","desc":"主屋の西後方に南面して建つ。土蔵造二階建で、一階正面に大戸、二階東面に開口部を設ける。一階正面の出入口は、鳥居型の額縁に、掛子塗の大戸を吊る。扉内面に鏝絵を飾るなど高い左官技術を見せる。小屋は垂木構造とする。地域の歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010569"},{"id":"00011915","register_sub_id":"101","register_pk":"210922","name":"梅嶋家住宅主屋","kana":"うめじまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区四ツ屋町一丁目2993-27","lat":37.933792,"lng":139.045312,"geo_status":"db","era":"昭和元年頃／平成27年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-457","desc":"市街地北部の海岸付近に建つ。道路から後退して建ち、塀で囲んだ前庭の右に切妻造の妻入の玄関を付け、一階は座敷、仏間、台所を二階は矩折に三室を配す。床の間の下地窓や、寄付の丸窓、欄間などに数寄屋風意匠が見られ、地域の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011915"},{"id":"00015424","register_sub_id":"101","register_pk":"533439","name":"榎並家住宅主屋","kana":"えなみけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市江南区砂岡二丁目3808","lat":37.86531944,"lng":139.12006389,"geo_status":"db","era":"江戸後期／大正後期、昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積246㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0601","desc":"新潟市南郊の集落の微高地に位置し、敷地北寄りに南面して建つ農家の主屋。寄棟造茅葺で正面東寄りに張出す玄関などを桟瓦葺下屋とする。二一畳のオチャノマを中心に上手にザシキとカミザシキ、下手にダイドコロを配す。当地の伝統的平面を良く示す近世民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015424"},{"id":"00015425","register_sub_id":"101","register_pk":"533440","name":"榎並家住宅小屋","kana":"えなみけじゅうたくこや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市江南区砂岡二丁目3808","lat":37.86545278,"lng":139.12018333,"geo_status":"db","era":"江戸末期／昭和前期改修、同30年代増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造一部コンクリートブロック造平屋建、瓦葺、建築面積80㎡","structure_material":"木造一部コンクリートブロック造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0602","desc":"主屋北東に南面して建つ東西棟の小屋。木造平屋建の当初部の西端にコンクリートブロック造の道具入を増築し、前面に吹放ちの土間を設けて、屋根を切妻造セメント瓦葺とする。当初部は東から布団室、書庫、炭小屋に区画する。旧家の生活様態を伝える付属屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015425"},{"id":"00001601","register_sub_id":"101","register_pk":"102591","name":"燕喜館（旧斎藤家住宅）主屋","kana":"えんきかん（きゅうさいとうけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区一番堀通町1-2","lat":37.914932,"lng":139.037872,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0073","desc":"幕末期の新潟の名士斎藤家の座敷棟を移築したもの。現在，蓮池を望む白山公園内に位置する。座敷とその縁側は池に向けられ庭と一体となり開放感ある空間を作る。全体的に数寄屋風でまとめた内部には銘木が多く用いられ，襖絵・欄間等に趣向が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001601"},{"id":"00008661","register_sub_id":"101","register_pk":"149382","name":"大橋家住宅主屋","kana":"おおはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市小国町法末字谷内681","lat":37.26650969,"lng":138.74227746,"geo_status":"db","era":"江戸後期／昭和30年頃・昭和後期・平成17年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積154㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0334","desc":"山間の集落に所在する農家。桁行13ｍ梁間8.2ｍの寄棟造茅葺で、正面に下屋と出入口の切妻屋根を設け、側面にウマヤを付設する。出入口の奥はもと土間のニワとダイドコとし、右手を4間取としてデイやネマを配する。当地方の典型的な民家の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008661"},{"id":"00009133","register_sub_id":"101","register_pk":"164686","name":"大鋸町ますや主屋","kana":"おがまちますやしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市仲町六丁目字大鋸町45-1","lat":37.11833773,"lng":138.24409948,"geo_status":"db","era":"明治元年／昭和34年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"仲町通りに西面する町家で、正面に雁木を差出す。木造平屋建、建築面積83平方メートル、切妻造鉄板葺。南にトオリニワを通し、前からミセ、チャノマ、ザシキ、ドインを配し、ミセは天井を張らず小屋組を現す。建ちが低く、高田の町家の古い形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009133"},{"id":"00011100","register_sub_id":"101","register_pk":"205207","name":"おっこの木主屋","kana":"おっこのきしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県小千谷市真人町十二所戊2518","lat":37.246836,"lng":138.753496,"geo_status":"db","era":"慶応3／平成22改修","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造2階建、茅葺（鉄板仮葺）、建築面積182㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0442","desc":"若栃集落に位置する。建ちの高い寄棟造茅葺の本屋正面に切妻造妻入の前中門が取り付く典型的な中門造農家で、背面に切妻造の後中門が付く。一階西寄りと中門二階に座敷を持ち、床や付書院などに秀逸な造形がみられる。当地方の中門造農家の特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011100"},{"id":"00012317","register_sub_id":"101","register_pk":"531641","name":"温泉御宿龍言本館（旧松崎家住宅主屋）","kana":"おんせんおんやどりゅうごんほんかん（きゅうまつざきけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県南魚沼市坂戸字道端1-6","lat":37.05793611,"lng":138.88325278,"geo_status":"db","era":"明治前期／昭和44年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、金属板葺、建築面積218㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"15-486","desc":"近隣集落から移築した民家で、切妻造平入の前後に切妻屋根の中門を突出する。前中門の玄関脇に天井の高い広間を設け、その奥に相の間を挟んで座敷二室を前後に並べている。宿泊施設に転用されているが、内外とも当地の上層農家の形式をよく留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012317"},{"id":"00005113","register_sub_id":"101","register_pk":"106103","name":"割烹吉源土蔵","kana":"かっぽうよしげんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市寺町1437","lat":38.22433381,"lng":139.47647894,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0190","desc":"主屋の南方に位置し，東西棟，切妻造，桟瓦葺の覆屋で囲う。桁行２間，梁間３間の規模で，切妻造，平入の２階建土蔵で，１階北面に戸口を設け，２階北面に観音開きの扉付きの窓を開く。棟梁は遠藤鉀子郎。屋敷後方の敷地利用を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005113"},{"id":"00011663","register_sub_id":"101","register_pk":"210679","name":"鴨井家住宅主屋","kana":"かもいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市板倉区田屋字久保田20","lat":37.052822,"lng":138.313959,"geo_status":"db","era":"江戸末期／昭和45年・平成2年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、茅葺一部鋼板葺、建築面積237㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"15-0455","desc":"当地の庄屋を務めた大型農家。桁行一〇間、梁間四間の寄棟造、茅葺。主体部の前面に玄関、背面に二階建の中門がそれぞれ突出する形式とする。平面は広間型三間取で、オクザシキは座敷飾りを備える。大きな茅葺屋根が地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011663"},{"id":"00011664","register_sub_id":"101","register_pk":"210680","name":"鴨井家住宅土蔵","kana":"かもいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市板倉区田屋字久保田20","lat":37.052668,"lng":138.314153,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造及び土蔵造2階建、鋼板葺、建築面積47㎡、渡廊下付","structure_material":"木造及び土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"15-0456","desc":"木造二階建の蔵前と土蔵造二階建の土蔵部からなる。土蔵は、腰をモルタル洗い出しとし石積風に目地をつくる。蔵前は下見板張とし、妻壁上部は漆喰塗で小屋束と貫、棟木をあらわす。土蔵の高い位置までモルタル仕上げとするなど、豪雪地帯の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011664"},{"id":"00015167","register_sub_id":"101","register_pk":"530591","name":"川俣家住宅（旧渋谷家住宅）長屋門","kana":"かわまたけじゅうたく（きゅうしぶやけじゅうたく）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県三条市月岡字瀬戸山4963-1","lat":37.604325,"lng":138.99072222,"geo_status":"db","era":"天保9年(1838)／昭和55年移築","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"15 - 0598","desc":"五十嵐川西岸の敷地に移築した旧本陣の長屋門。通りに南面して建つ桁行１５間半、梁間２間、切妻造平入桟瓦葺で、中央東寄りを門口とし、両脇に各一室の土間を配す。軒をせがい造とし、門口にケヤキの一枚板の板扉を吊るなど、間口長大で豪壮な構えの長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015167"},{"id":"00005955","register_sub_id":"101","register_pk":"106940","name":"岸家住宅主屋","kana":"きしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市横枕町606","lat":37.40319387,"lng":138.85158102,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積170㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0238","desc":"市内平野部に位置する。桁行１２間，梁間５間半規模，寄棟造，茅葺の大型民家で，北方をもとは広い土間として，南方を床上部とし，東南に座敷を配す。棟の中央に煙出しを載せる。中越地震で大きな被害を受けたが，応急復旧され，外観は旧状をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005955"},{"id":"00002901","register_sub_id":"101","register_pk":"103891","name":"木地屋民俗資料館","kana":"きじやみんぞくしりょうかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県糸魚川市大字大所797-1","lat":36.87496422,"lng":137.8307237,"geo_status":"db","era":"江戸末期／平成8移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、鉄板葺、建築面積123㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0119","desc":"江戸末期に飛騨から移住した木地師集落にある民家。集落内で移建し，民俗資料館として活用している。寄棟造・もと茅葺で手斧梁の梁組や小屋の叉首組など一般の農家と同様であるが，内部は茶の間を除いて作業場等とした２階床があり，高い外壁に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002901"},{"id":"00006275","register_sub_id":"101","register_pk":"107259","name":"季節宿國安主屋","kana":"きせつやどくにやすしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三島郡出雲崎町大字田中450","lat":37.50470604,"lng":138.69053381,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、茅葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"15 － 0258","desc":"南東を向いて建つ農家建築。桁行８間，梁間５間半規模の寄棟造，茅葺で，平入とする。建築当初は梁行が１間短く，整形四間取であったが，早い時期に改修がなされ，中廊下が設けられた。反りのある棟を置き，軒をせがい造で支えるなど地方的特色をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006275"},{"id":"00006276","register_sub_id":"101","register_pk":"107260","name":"季節宿國安土蔵","kana":"きせつやどくにやすどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三島郡出雲崎町大字田中450","lat":37.50461141,"lng":138.69057166,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"15 － 0259","desc":"主屋前方に東面して建つ桁行３間，梁間２間規模の土蔵造２階建。切妻造，桟瓦葺の置屋根を置き，平入とする。正面に奥行１間の蔵前を設け，西面，南面にそれぞれ窓を設ける。外壁は漆喰仕上げとし，上部に鉢巻を廻す。主屋とともに風趣に富む敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006276"},{"id":"00001251","register_sub_id":"101","register_pk":"102241","name":"吉川家住宅主屋","kana":"きっかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町195","lat":38.22431442,"lng":139.47894942,"geo_status":"db","era":"明治12頃","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積315㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"15 － 0032","desc":"大町通りと市役所通りに挟まれた東西に長い敷地の中央部に建つ。鮭の加工販売を営む商家の住宅で、明治１２年の大火直後の再建と伝える。北側は２列の部屋列とし、西北端の座敷部分を２階建とする。南側は鮭加工の場として通り土間としている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001251"},{"id":"00001252","register_sub_id":"101","register_pk":"102242","name":"吉川家住宅土蔵","kana":"きっかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県村上市大町195","lat":38.22431431,"lng":139.47910603,"geo_status":"db","era":"天保12","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造２階建，瓦葺，建築面積161㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"15 － 0033","desc":"主屋の背後に建つ切妻造、桟瓦葺、妻入、総２階の土蔵で、棟札により建設年代が判明する。内部に２列４本の柱を持つ規模の大きな土蔵で、造り酒屋を営んだ時期の酒蔵とされる。村上市の旧市街地における明治維新前の建築遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001252"},{"id":"00004682","register_sub_id":"101","register_pk":"105672","name":"ギャラリー十三代目長兵衛","kana":"ぎゃらりーじゅうさんだいめちょうべえ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県柏崎市学校町3-12","lat":37.37087679,"lng":138.55664453,"geo_status":"db","era":"江戸末期頃／明治後期移築／平成15曳家","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期頃","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"15 － 0174","desc":"南側及び西側が接道する敷地の南西隅に南面して建つ。土蔵造２階建，切妻造，桟瓦葺で，棟を東西に置く。西面妻壁２階には窓を開く。外壁は腰を縦板張，上部を白漆喰で仕上げ，軒に鉢巻を廻し，扉や楣を黒漆喰で飾る。現在はギャラリーとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004682"},{"id":"00005119","register_sub_id":"101","register_pk":"106109","name":"ギャラリーやまきち奥の土蔵","kana":"ぎゃらりーやまきちおくのどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市肴町1678","lat":38.2243744,"lng":139.46895782,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0196","desc":"南北に長い敷地の北東端に南北棟で建つ。桁行３間半，梁間３間規模の妻入２階建土蔵で，屋根は桟瓦葺の置屋根式とし，南妻面に下屋を差し掛ける。外壁は腰下見板張，上部は漆喰塗で，北及び西面は板壁を建てて囲い，商家の屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005119"},{"id":"00005117","register_sub_id":"101","register_pk":"106107","name":"ギャラリーやまきち主屋","kana":"ぎゃらりーやまきちしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市肴町1678","lat":38.22402828,"lng":139.46892348,"geo_status":"db","era":"明治初期／昭和4増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0194","desc":"通りに南面して建つ。桁行７間，梁間７間半，切妻造，桟瓦葺，平入の２階建町家で，東方を土間とし，西方にチャノマとザシキを配する。西方２階は増築で，棟を高くつくる。外観は近年の復原によるもので，村上の歴史的な町並み景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005117"},{"id":"00005118","register_sub_id":"101","register_pk":"106108","name":"ギャラリーやまきち土蔵","kana":"ぎゃらりーやまきちどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市肴町1678","lat":38.22423094,"lng":139.46888859,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"15 － 0195","desc":"南北に長い敷地の中央北寄りに南北棟で建つ。桁行３間半，梁間２間半の規模とし，平入の２階建土蔵で，屋根は置屋根，桟瓦葺。東面南寄りに戸口を設け，中庭に面する南妻面の開口部廻りを丁寧につくる。主屋ザシキに向き合い，中庭を囲う要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005118"},{"id":"00012515","register_sub_id":"101","register_pk":"367810","name":"旧浅島家住宅主屋","kana":"きゅうあさしまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市八幡2043-2","lat":37.986542,"lng":138.34494,"geo_status":"geocoded","era":"安政5年（1858）／昭和35年移築","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、茅葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0489","desc":"島内陸部の高台から移築した農家主屋。寄棟造茅葺で東面して建ち、正面中央部に煙出しをもつ。内部は南を下手として土間と板敷の台所を設け、中央表に12畳半敷の広間を取り、上手の奥を本座敷とする。建築年代が明らかで典型的な島内伝統民家の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012515"},{"id":"00009934","register_sub_id":"101","register_pk":"196081","name":"旧飯田家住宅主屋","kana":"きゅういいだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市大島区菖蒲字東沖318-1","lat":37.07649343,"lng":138.51913163,"geo_status":"db","era":"嘉永6","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造2階建、茅葺、建築面積313㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"15 － 0390","desc":"山間地の敷地に西面して建つ茅葺民家。北寄りの土間前面に入母屋造の大きな中門を構え、越後地方に特徴的な中門造の形式をもつ。床上部は板敷の広間の奥をブツマなどに間仕切り、上手の座敷も一部張出す。豪雪地帯らしく、木太く豪壮な軸部をみせる大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009934"},{"id":"00013074","register_sub_id":"101","register_pk":"368250","name":"旧五十嵐家住宅主屋","kana":"きゅういからしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県阿賀野市金屋字川端340-5他","lat":37.82896944,"lng":139.26265278,"geo_status":"db","era":"明治前期／明治20年増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積510㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0515","desc":"阿賀野市街東方の田園地帯に位置する元地主の主屋。敷地東寄りに南面して建ち、南北棟の正面に式台玄関を設け、背後の東西棟に続き、その東端から北に南北棟が突出する。内部に豪壮なつくりの茶の間や上質の材を用いた座敷を備え、内外共に優秀な意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013074"},{"id":"00006747","register_sub_id":"101","register_pk":"107730","name":"旧石崎家住宅（石泉荘）茶室","kana":"きゅういしざきけじゅうたく（せきせんそう）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市諏訪町3-11-21","lat":37.940937,"lng":139.328232,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"15 － 0262","desc":"屋敷地の西南部に位置し、屋敷地内を南北に流れる新発田川の左岸に建つ。もと藩医の隠居所と伝える。４畳半の茶室と２畳大の水屋からなる桁行２間半、梁間１間半、東西棟、切妻造、桟瓦葺の木造平屋建で、東面に下屋を付けて玄関とする。屋敷地の点景となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006747"},{"id":"00013077","register_sub_id":"101","register_pk":"368253","name":"旧伊藤家住宅米土蔵","kana":"きゅういとうけじゅうたくこめどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市黒川字上町1432-2他","lat":38.07293333,"lng":139.43967222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0518","desc":"土蔵南東側に南北棟で建ち、切妻造、置屋根形式の桟瓦葺で、西面に金属板葺の下屋を付す。外壁漆喰塗で一階を海鼠壁とし、二階は南面を除く三面に小窓を穿つ。内部の北寄りに立てる太い柱を境に北に二階を設け、南は吹抜とする。広壮な内部をもつ大型の米蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013077"},{"id":"00013078","register_sub_id":"101","register_pk":"368254","name":"旧伊藤家住宅作業場","kana":"きゅういとうけじゅうたくさぎょうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"新潟県","address":"新潟県胎内市黒川字上町1432-2他","lat":38.07281389,"lng":139.43936667,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0519","desc":"敷地中央南寄りに東西棟で建ち、二階建、切妻造桟瓦葺で、南面に鉄板葺の下屋を設ける。外壁は真壁中塗仕上で腰を板張とし、各面にガラス窓を開ける。一階は土間で農機具や米などを保管し、二階は米の選別、俵製作などを行った。豪農の屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013078"},{"id":"00013076","register_sub_id":"101","register_pk":"368252","name":"旧伊藤家住宅土蔵","kana":"きゅういとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県胎内市黒川字上町1432-2他","lat":38.07308889,"lng":139.43955833,"geo_status":"db","era":"明治39年","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0517","desc":"大庄屋を務めた伊藤家の旧宅地北寄りに東西棟で建つ、桁行六間の二階建土蔵。切妻造、置屋根形式の桟瓦葺で、南面を戸口とし吹放しの下屋を設ける。外壁漆喰塗で鉢巻を廻らし一階を海鼠壁とし、一階東面と二階南面に小窓を穿つ。旧家の家財を納めた大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013076"},{"id":"00010280","register_sub_id":"101","register_pk":"199053","name":"旧今井銀行店舗","kana":"きゅういまいぎんこうてんぽ","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県燕市吉田下町5323他","lat":37.692425,"lng":138.878838,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造3階建、建築面積106㎡、塀付","structure_material":"煉瓦造3階建","registered":"2014.12.19(平成26.12.19)","register_no":"15-0397","desc":"主屋の北に建つ今井家設立の銀行建築。煉瓦造三階建で、鉄骨の床梁や鉄筋コンクリート造の屋上スラブなど進んだ技法を取入れる。外壁は焼過煉瓦の小口積に見せ、窓廻りなど要所を花崗岩で装飾し、頂部は銅板張のパラペットを立上げるなど凝った意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010280"},{"id":"00009748","register_sub_id":"101","register_pk":"195577","name":"旧今井家住宅新館","kana":"きゅういまいけじゅうたくしんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県三条市本町3-316-2","lat":37.62855091,"lng":138.9559559,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"15 － 0385","desc":"道路南側敷地の南寄りに建つ木造二階建で、入母屋造桟瓦葺。北面西寄りに起り屋根の玄関を突出する。一階は八畳二室に広縁を廻らし、土縁を設けてガラス窓をたて込む。二階も八畳二室で縁のガラス窓の外に高欄がつく。室内の造作も丁寧な近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009748"},{"id":"00004741","register_sub_id":"101","register_pk":"105731","name":"旧小林古径邸","kana":"きゅうこばやしこけいてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県上越市本城町字越後44-1","lat":37.11046596,"lng":138.25477672,"geo_status":"db","era":"昭和9／平成13移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積151㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"15 － 0184","desc":"はじめ東京馬込に建築，その後郷里に移築された小林古径の旧宅。木造，２階建，切妻造，桟瓦葺で，見隠れに補強鉄物を用い長押を省略し努めて木柄を細くするなど，新しい和風意匠を目指す。設計吉田五十八，数寄屋大工岡村仁三による注目すべき近代住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004741"},{"id":"00011108","register_sub_id":"101","register_pk":"205215","name":"旧鈴木家住宅主屋","kana":"きゅうすずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦スワノ木1190-1","lat":37.702564,"lng":138.829592,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積245㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0450","desc":"もと社家の住宅で、宿坊部分と居住部分から構成される。宿坊部分は二階建切妻造南北棟で、その西面に平屋建切妻造瓦葺の居宅部を接続し、東面に式台を備えた起り破風の玄関を構える。連続する座敷や祖霊室など社家住宅の特徴をよく備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011108"},{"id":"00011109","register_sub_id":"101","register_pk":"205216","name":"旧鈴木家住宅土蔵","kana":"きゅうすずきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦スワノ木1190-1","lat":37.702473,"lng":138.829636,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0451","desc":"主屋の南西にあり平屋の蔵前で接続する。北を正面とし、土蔵造二階建瓦葺で、置屋根形式である。桁行四・六メートル、梁間三・六メートル。外壁の上部や内部壁面を漆喰塗仕上げとし、軒下には軒蛇腹をめぐらす。社家住宅の生活様態をよく示す家財蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011109"},{"id":"00003083","register_sub_id":"101","register_pk":"104073","name":"旧第四銀行村上支店長住宅主屋","kana":"きゅうだいしぎんこうむらかみしてんちょうじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県村上市小町1358-2","lat":38.22568186,"lng":139.47814424,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0144","desc":"村上信用組合理事長宅として建設。たちの高い入母屋造，桟瓦葺の木造２階建，起り破風車寄玄関付，外部簓子下見の和風住宅で，内部は黒柿等の銘木を用い，床飾りや建具も凝った造作になる。棟札から菅原建吉の設計，大工棟梁飯田文次郎が判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003083"},{"id":"00000962","register_sub_id":"101","register_pk":"101952","name":"旧武石家住宅薪小屋","kana":"きゅうたけいしけじゅうたくたきぎごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字麓7056","lat":37.68123573,"lng":138.82230173,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建，茅葺，建築面積10㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"15 － 0029","desc":"村指定文化財である主屋の南方，味噌蔵の西後方に位置する。桁行２間，梁間１間半の規模で，切妻造，茅葺，平入，側柱のみの吹放ち建物。側柱は土台に建ち，２筋の貫を回す。素朴で小規模な小屋ではあるが，茅屋根のヴォリュームが相応の存在感を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000962"},{"id":"00000961","register_sub_id":"101","register_pk":"101951","name":"旧武石家住宅味噌蔵","kana":"きゅうたけいしけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字麓7056","lat":37.68130493,"lng":138.8224823,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建，茅葺，建築面積20㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"15 － 0028","desc":"村指定文化財である主屋の南手前に建つ。桁行３間，梁間２間の規模で，平入，寄棟造，茅葺，出入口に庇を付ける。部材や構法が上質であることから，当初は道具蔵であったとみられている。屋敷構えを構成する主要建造物として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000961"},{"id":"00012516","register_sub_id":"101","register_pk":"367811","name":"旧土屋家住宅土蔵","kana":"きゅうつちやけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市八幡2043-2","lat":37.986542,"lng":138.34494,"geo_status":"geocoded","era":"明治23年頃／昭和41年移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0490","desc":"島中央平野の南部から移築した穀物蔵。土蔵造二階建、置屋根式の切妻造で、南面して建ち、正面中央に扉口を開いて下屋を付す。上下階とも板敷で、垂木小屋組とし、一階西面に穀物庫を備える。農家に欠かせない附属建物で、伝統的な土蔵の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012516"},{"id":"00004342","register_sub_id":"101","register_pk":"105332","name":"旧中澤家住宅離れ（平出修旧居）","kana":"きゅうなかざわけじゅうたくはなれ（ひらいでしゅうきゅうきょ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市大町2丁目字馬出37-1","lat":37.10820681,"lng":138.24516407,"geo_status":"db","era":"明治29頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"15 － 0173","desc":"床と違棚，付書院を備えた６畳とその東の長４畳に広縁や廊下を廻し，台所や玄関を付設する。欄間や建具ほかに繊細な数寄屋意匠がみられる近代和風建築であるとともに，近代上越地域の上層住宅において応接のために建設された離れ座敷の数少ない遺例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004342"},{"id":"00013071","register_sub_id":"101","register_pk":"368248","name":"旧西脇家住宅主屋","kana":"きゅうにしわきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県小千谷市本町二丁目96-1他","lat":37.30925278,"lng":138.79553333,"geo_status":"db","era":"明和7年（1770）／昭和54年改修","year":1770,"year_source":"db","year_min":1770,"year_max":1770,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0512","desc":"小千谷市街地に建つ豪商の住宅。通りに南面して建ち、木造平屋建、切妻造妻入金属板葺で、外壁は漆喰塗の大壁で腰を下見板張とする。内部は東側を通り土間とし、床上部は東西二列に室を並べ、表に茶の間と仏間、奥に座敷等を配する。商人町の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013071"},{"id":"00013072","register_sub_id":"101","register_pk":"368249","name":"旧西脇家住宅離座敷","kana":"きゅうにしわきけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県小千谷市本町二丁目96-1他","lat":37.30949167,"lng":138.79537778,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積218㎡、渡廊下付","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0513","desc":"主屋の北側に渡廊下を介して建つ。東西棟の木造二階建、入母屋造銅板葺で、上下階共に上段と次の間を東西に並べ、西・南面に畳廊下を廻して庭への眺望を得、二階は北西に茶室を設ける。曾禰達蔵らの設計による、良材をふんだんに用いた意匠優秀な離座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013072"},{"id":"00014346","register_sub_id":"101","register_pk":"511335","name":"旧藤田家住宅（いたくら亭）主屋","kana":"きゅうふじたけじゅうたく（いたくらてい）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県上越市板倉区針字東町894-3","lat":37.0496,"lng":138.29302778,"geo_status":"db","era":"大正12年／昭和６３年・平成１３年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積157㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0569","desc":"旧板倉町中心地にある医家の住居で、診療も行った。二階建切妻造座敷棟の西面北に、入母屋造医院玄関棟を付し、玄関庇の破風を連ねる。当初は南に住居玄関棟が並ぶ。座敷棟は各階続き座敷、二階は天井高く関田山地を望む。玄関に床構え付待合を配す和風医院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014346"},{"id":"00014347","register_sub_id":"101","register_pk":"511336","name":"旧藤田家住宅（いたくら亭）土蔵","kana":"きゅうふじたけじゅうたく（いたくらてい）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市板倉区針字東町894-3","lat":37.04968889,"lng":138.29318333,"geo_status":"db","era":"昭和元年／平成１５年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0570","desc":"板倉町中心地に所在する医家の土蔵。主屋の北に位置して渡り廊下で接続する。蔵前に物置と和室からなる二階建を付し、全体を覆屋で囲う。中央に太い柱を立てて牛梁を支え、登梁形式とする。板張覆屋の開口部から立派な掛子塗の扉が覗く雪国の土蔵の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014347"},{"id":"00013070","register_sub_id":"101","register_pk":"368247","name":"旧武者家別邸（苔香荘武者亭）","kana":"きゅうむしゃけべってい（たいこうそうむしゃてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新発田市中央町一丁目357-1","lat":37.948675,"lng":139.32896667,"geo_status":"db","era":"明治中期／大正14年増築、平成21年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0511","desc":"敷地南辺中央に北面して建つ。正面に入母屋造の玄関を付した平屋建の南西に、入母屋造の二階建を雁行して増築し、いずれも座敷の周囲に縁を廻らす。平屋部東西二室、増築部上下階に座敷飾を設け、各室で趣向を変える。上質なつくりの迎賓用の別邸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013070"},{"id":"00013069","register_sub_id":"101","register_pk":"368246","name":"旧村山家別邸（苔香荘苔松庵）","kana":"きゅうむらやまけべってい（たいこうそうたいしょうあん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新発田市中央町一丁目357-1","lat":37.94880833,"lng":139.3293,"geo_status":"db","era":"明治前期／昭和42年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0510","desc":"新発田城跡南東に位置するもと商家の別邸。敷地北東隅に建つ寄棟造桟瓦葺で、軒先を銅板葺とする。10畳和室の東に座敷飾を備えた10畳、南に仏間を配してＬ字形平面とし、周囲に縁を廻らす。庭園に向けた開放的なつくりで、迎賓用に相応しい瀟洒な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013069"},{"id":"00004533","register_sub_id":"101","register_pk":"105523","name":"旧横尾義智家雪室","kana":"きゅうよこおよしともけゆきむろ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県上越市安塚区行野1146-1","lat":37.10885712,"lng":138.4858257,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"コンクリート造、面積36㎡、深さ3.0m","structure_material":"コンクリート造","registered":"2005.02.09(平成17.02.09)","register_no":"15 － 0175","desc":"横尾義智生家の敷地内，斜面を切り開いた平地に建設され，周囲を杉林が取り囲む。上部６ｍ四方，底面４ｍ四方，深さ３ｍ規模の竪穴で，底面及び法面をコンクリートで造る。新潟県有数の豪雪地帯における雪利用の歴史や生活文化を知る上で貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004533"},{"id":"00009134","register_sub_id":"101","register_pk":"164687","name":"幸村家住宅主屋","kana":"こうむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県上越市仲町六丁目字大鋸町146-1","lat":37.11726602,"lng":138.24366309,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積80㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"木造2階建、建築面積80平方メートル、切妻造桟瓦葺で鋳鉄製の雁木をつくる。トオリニワ沿いにミセ、チャノマ、ザシキを並べ、チャノマ上部に組む井桁状の梁組と5重の小屋貫を通して高窓から採光する構成は、高田における町家の内部空間の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009134"},{"id":"00014343","register_sub_id":"101","register_pk":"511332","name":"小鍛冶屋（旧高島家住宅）主屋","kana":"こかじや（きゅうたかしまけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市西蒲区岩室温泉字居掛666","lat":37.73794722,"lng":138.83821667,"geo_status":"db","era":"江戸末期／明治中期・大正前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積247㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0566","desc":"岩室温泉郷の北端に位置する町家型住宅。二階建切妻造で元は板葺、増改築を繰返した複雑な構成。正面側は玄関土間から続き座敷で、奥座敷は吹抜で高窓を設ける。二階も床構え付座敷で接客空間とする。街道との間に前栽を置く旧家の表構えは歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014343"},{"id":"00005427","register_sub_id":"101","register_pk":"106415","name":"小林家住宅主屋","kana":"こばやしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市中央区南毘沙門町2538","lat":37.92599292,"lng":139.05103229,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積153㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"15 － 0200","desc":"南北に長い敷地南辺の道路境からやや後退して建ち，桁行１１間，梁間５間の規模で，木造２階建，寄棟造，桟瓦葺。壁を押縁下見板張とする。正面の入母屋造の玄関から廊下で各室が連絡され，２階に続き間座敷を設けるなど，新しい住宅要素がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005427"},{"id":"00001574","register_sub_id":"101","register_pk":"102564","name":"斎藤家住宅主屋","kana":"さいとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市中央区関屋本村町1-148-1","lat":37.91234117,"lng":139.01964997,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積395㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0046","desc":"斎藤家は江戸時代には米沢藩の陣屋とされていた旧家。主屋は戊辰戦争で焼失し，その後に再建された。大規模な切妻造・妻入の形式で，外観の妻面は直梁と貫を数段重ねた構成とし，内部は茶の間など豪快な梁組をみせるが，座敷を瀟洒な書院風にまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001574"},{"id":"00014586","register_sub_id":"101","register_pk":"515128","name":"齋藤家住宅土蔵","kana":"さいとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市南区新飯田字古町1850-1","lat":37.68582778,"lng":138.98225278,"geo_status":"db","era":"明治15年／昭和56年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"15 - 0581","desc":"越後平野中ノ口川東岸の旧家の土蔵。切妻造桟瓦葺、主屋と戸前を介し妻入で接続する二階建。垂木太く、柱を密に立てる堅固な造りで、内壁は漆喰仕上で腰無目の下を板壁とする。屋敷の小高い土地に建てるなど水害に備えた造りで、当地旧家の屋敷構えを形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014586"},{"id":"00001575","register_sub_id":"101","register_pk":"102565","name":"斎藤家住宅土蔵","kana":"さいとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市中央区関屋本村町1-148-1","lat":37.912361,"lng":139.01941838,"geo_status":"db","era":"江戸後期／弘化2（1845）移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0047","desc":"敷地最奥，主屋の北西側に建つ土蔵は，弘化２年頃に亀田町の堀家のものを移築したと伝える。切妻造・桟瓦葺で置き屋根式とし，２階建で両側面に各階の窓を設け，外壁は漆喰塗とする。保存状態も良好で，江戸期の土蔵形式をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001575"},{"id":"00014585","register_sub_id":"101","register_pk":"515127","name":"齋藤家住宅離れ","kana":"さいとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市南区新飯田字古町1850-1","lat":37.68590556,"lng":138.98243611,"geo_status":"db","era":"明治中期／昭和42年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、鉄板葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"15 - 0580","desc":"越後平野中ノ口川東岸の旧家の離れ。屋敷南の庭園に南面した寄棟造鉄板葺の平屋建。北側に切妻造玄関を設け、東と南面に霧除庇付縁側を巡らす。座敷は北面に書院、西面に地袋付床を構え、丸炉を切る。落掛等の用材に凝り、庭園に向けて開放的な造りの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014585"},{"id":"00008431","register_sub_id":"101","register_pk":"134827","name":"坂田家住宅主屋","kana":"さかたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県五泉市土堀字上ノ代295","lat":37.73351732,"lng":139.21787142,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積301㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0325","desc":"通りに南面した敷地の北西寄りに建つ。木造平屋建、東西棟で東入母屋造、西切妻造とし、南面中央に入母屋造の玄関を突出する。桟瓦葺。正面間口二〇メートルを越える大規模な住宅で、奥座敷や茶の間などの主要居室は近世農家の落ち着きのある趣を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008431"},{"id":"00008432","register_sub_id":"101","register_pk":"134828","name":"坂田家住宅新倉","kana":"さかたけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県五泉市土堀字上ノ代295","lat":37.73326857,"lng":139.21779182,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0326","desc":"主屋の南方、庭を挟んで建つ。木造二階建、東西棟の置屋根、切妻造桟瓦葺。桁行九・一メートル梁間四・九メートルで、北面に蔵前を設ける。外壁は、漆喰仕上げで、腰を黒漆喰とし、内部は板張とする。密に柱を配し、外壁にも現す凝ったつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008432"},{"id":"00008435","register_sub_id":"101","register_pk":"134831","name":"坂田家住宅堆肥舎","kana":"さかたけじゅうたくたいひしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県五泉市土堀字上ノ代295","lat":37.73369642,"lng":139.21775203,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0329","desc":"敷地の北西隅に位置する。木造二階建、東西棟の切妻造桟瓦葺で南面を葺き降ろす。桁行七・三メートル梁間六・四メートル。外壁は荒壁の真壁造で、妻面には小屋組も現す。堆肥や藁の保管や、家畜の飼育を行った施設で、豪農の屋敷構えを構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008435"}];
